<?php

date_default_timezone_set('Asia/Shanghai');

use Workerman\Lib\Timer;

// ==================== 常量定义 ====================

define('ERTONG', 1);
define('ERTIAO', 2);
define('WUTONG', 3);
define('WUTIAO', 4);
define('BAWAN', 5);
