    WUTONG    => [3 => 3,  4 => 5,   5 => 12],
    WUTIAO    => [3 => 3,  4 => 5,   5 => 12],
    BAWAN     => [3 => 5,  4 => 10,  5 => 15],
    BAIBAN    => [3 => 6,  4 => 15,  5 => 30],
