            'is_boom_round'    => false,
        ];

        if (!$is_free_round) {
            return $params;
        }

        // 进入免费时的档位设置
        if ($this->free_prize_level ==<?php

date_default_timezone_set('Asia/Shanghai');

use Workerman\Lib\Timer;

// ==================== 常量定义 ====================

