            'total_min_score'  => 0,
            'total_need_score' => 0,
            'need_boost'       => false,
            'boost_min_score'  => 0,
            'boost_max_score'  => PHP_INT_MAX,
            'is_boom_round'    => false,
        ];

        if (!$is_free_round) {
            return $params;
        }

