            'total_min_score'  => 0,
            'total_need_score' => 0,
            'need_boost'       => false,
            'boost_min_score'  => 0,
            'boost_max_score'  => PHP_INT_MAX,
            'is_boom_round'    => false,
        ];

        if (!$is_free_round) {
            return $params;
        }

        // 进入免费时的档位设置
        if ($this->free_prize_level == FREE_LEVEL_NORMAL) {
            $max_double       = 15;
            $reroll_min_double = 2;
        } elseif ($this->free_prize_level == FREE_LEVEL_BIG) {
            $max_double       = 130;
            $reroll_min_double = 20;
        } else {
            $max_double       = 300;
            $reroll_min_double = 80;
        }

        $params['max_score']       = $this->use * $max_double;
        $params['total_max_score'] = $this->use * $this->free_total_limit_double;
        $params['total_left_score']= max(0, $params['total_max_score'] - $this->free_get);
        $params['reroll_min_score']= $this->use * $reroll_min_double;
        $params['total_min_score'] = $this->use * $this->free_total_min_double;
        $params['total_need_score']= max(0, $params['total_min_score'] - $this->free_get);

        // 当前这转是不是指定的爆奖转?
        if (!$this->free_boom_used && $this->free_boom_left_count ><?php

date_default_timezone_set('Asia/Shanghai');

use Workerman\Lib\Timer;

// ==================== 常量定义 ====================

define('ERTONG', 1);
define('ERTIAO', 2);
define('WUTONG', 3);
define('WUTIAO', 4);
define('BAWAN', 5);
define('BAIBAN', 6);
define('HONGZHONG', 7);
define('FACAI', 8);
define('SANTONG', 9);
define('FREE', 10);
define('BAIDA', 11);
define('GAME_DOUBLE', 20);

// 控制逻辑中引用的外部常量
defined('MAX_WIN_SCORE') || define('MAX_WIN_SCORE', 1000000);

// 不同图案连击的赔付倍率表 (3连/4连/5连)
define('DOUBLE', [
    ERTONG    => [3 => 1,  4 => 3,   5 => 6],
    ERTIAO    => [3 => 1,  4 => 3,   5 => 6],
    SANTONG   => [3 => 2,  4 => 4,   5 => 10],
    WUTONG    => [3 => 3,  4 => 5,   5 => 12],
    WUTIAO    => [3 => 3,  4 => 5,   5 => 12],
    BAWAN     => [3 => 5,  4 => 10,  5 => 15],
    BAIBAN    => [3 => 6,  4 => 15,  5 => 30],
    HONGZHONG => [3 => 8,  4 => 20,  5 => 40],
    FACAI     => [3 => 10, 4 => 25,  5 => 50],
]);

// 图案出现概率 (普通地图 / 免费地图)
define('POSSIBLE',      [ERTONG => 50, ERTIAO => 50, SANTONG => 50, WUTONG => 30, WUTIAO => 30, BAWAN => 15, BAIBAN => 7,  HONGZHONG => 3, FACAI => 1, FREE => 200]);
define('FREEPOSSIBLE',  [ERTONG => 50, ERTIAO => 50, SANTONG => 50, WUTONG => 30, WUTIAO => 30, BAWAN => 10, BAIBAN => 3,  HONGZHONG => 2, FACAI => 1, FREE => 8]);

// 大奖评级 (3=大/2=中/1=小)
define('BIG_WIN', [3 => 40, 2 => 20, 1 => 10]);

// Wild 柱阈值 (万分之 N)
define('WILD_PERCENT', 5000);

// 跑马灯触发条件
define('HORSE', ['double' => 20, 'score' => 1]);

// 免费游戏档位
define('FREE_LEVEL_NORMAL', 0);   // 普通
define('FREE_LEVEL_BIG',    1);   // 大奖/超级
define('FREE_LEVEL_JACKPOT',2);   // 爆奖


/**
 * 麻将/老虎机游戏主逻辑
 */
class Table
{
    // ==================== 玩家状态 ====================
    private $userInfo = [];
    private $uid = 0;
    private $free = 0;             // 剩余免费次数
    private $map = [];             // 地图 (各轮)
    private $betGold = 0;          // 当前下注档位
    private $betDouble = 1;        // 当前下注倍率
    private $roomRule = [];        // 房间配置
    private $use = 0;              // 实际消耗金币
    private $mTimer = 0;
    private $mapPossible = [];     // 当前地图概率表 (5列)
    private $wildPossible = [];    // Wild 出现概率 (5列)

    // ==================== 单局结算 ====================
    private $cur_result = [];
    private $deal_map = [];
    private $all_score = 0;        // 整局总得分
    private $all_free = 0;         // 整局获得的免费次数
    private $free_get = 0;         // 免费轮累计得分
    private $save_maps = [];
    private $distime = 0;
    private $freedistime = 0;
    private $next_free_count = 999;

    // ==================== 免费保底 ====================
    private $normal_round_count = 0;
    private $free_guarantee_threshold = 0;
    private $is_free_guarantee = false;
    private $free_guarantee_min = 150;
    private $free_guarantee_max = 250;

    // ==================== 免费游戏档位 ====================
    private $free_total_limit_double = 30;
    private $free_total_min_double = 0;
    private $free_prize_level = 0;
    private $force_free_trigger = false;

    private $free_boom_left_count = 0;   // 爆奖在剩余第几转出现
    private $free_boom_min_double = 0;
    private $free_boom_max_double = 0;
    private $free_boom_used = false;

    private $guarantee_bet_gold = 0;
    private $guarantee_bet_double = 0;
    private $guarantee_count = 0;

    // ==================== 胜负统计 ====================
    private $all_win = 0;


    // ================================================================
    // 构造与入口
    // ================================================================

    public function __construct($msg)
    {
        $this->roomRule = $msg;
        $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
        $this->resetCurResult();
    }

    public function All_RECV($message)
    {
        switch ($message['event']) {
            case 'Msg_MJHLT_Start':
                $this->Msg_MJHLT_Start($message);
                break;
            case 'Msg_Game_Out':
                $this->Msg_Game_Out($message);
                break;
            case 'Msg_Game_RoomInfo':
                $this->Msg_Game_RoomInfo($message);
                break;
            default:
                Logic::SendError($message['uid'], $message['event'], '');
                MyTools::msg('uid:' . $message['uid'] . '-----UnKnown!!!!!!!--------' . $message['event'], true);
                break;
        }
    }

    // ================================================================
    // 房间信息 / 进房 / 离线
    // ================================================================

    private function Msg_Game_RoomInfo($message)
    {
        if ($this->uid && $this->uid == $message['uid']) {
            Logic::SendRight($this->uid, 'Msg_Game_RoomInfo', [
                'free'         => $this->free,
                'all_score'    => $this->all_score,
                'all_free'     => $this->all_free,
                'curgrade'     => $this->betGold,
                'curdouble'    => $this->betDouble,
                'map'          => $this->map,
                'max_multiple' => max($this->roomRule['score_arr']),
                'level'        => $this->roomRule['level'],
                'score_arr'    => $this->roomRule['score_arr'],
                'double_arr'   => $this->roomRule['double_arr'],
                'base_arr'     => [GAME_DOUBLE],
                'min_gold'     => $this->roomRule['min_gold'],
                'max_gold'     => $this->roomRule['max_gold'],
                'bet_min'      => $this->roomRule['bet_min'] ?? 10000,
                'bet_max'      => $this->roomRule['bet_max'] ?? 200000,
                'gold'         => $this->userInfo['gold'],
            ]);
        } else {
            Logic::SendError($message['uid'], 'Msg_Game_RoomInfo', '无效操作');
        }
    }

    public function UserOnline($client_id, $uid)
    {
        Timer::del($this->mTimer);
        $this->Msg_Game_RoomInfo(['uid' => $uid]);
    }

    public function UserOff($uid)
    {
        $this->saveGameCache();
        $this->mTimer = Timer::add(60, function () {
            $this->Msg_Game_Out(['uid' => $this->uid]);
        }, [], false);
    }

    public function EnterRoom($msg)
    {
        $this->uid = $msg['uid'];
        $ret = DBInstance::GetGameCache($this->uid, $this->roomRule['gtype'], $this->roomRule['level']);

        if (!$ret) {
            $this->betGold   = min($this->roomRule['score_arr']);
            $this->betDouble = min($this->roomRule['double_arr']);
            DBInstance::InsertGameCache([
                'uid'        => $this->uid,
                'gtype'      => $this->roomRule['gtype'],
                'level'      => $this->roomRule['level'],
                'map'        => '[]',
                'bet_gold'   => $this->betGold,
                'bet_double' => $this->betDouble,
                'free'       => 0,
            ]);
            $this->guarantee_count = 0;
        } else {
            $this->map  = $ret['map'];
            $this->free = $ret['free'];

            if ($this->free > 0) {
                $this->betGold   = $ret['bet_gold'];
                $this->betDouble = $ret['bet_double'];
            } else {
                $this->betGold   = min($this->roomRule['score_arr']);
                $this->betDouble = min($this->roomRule['double_arr']);
            }

            $this->guarantee_count = $ret['vals']['guarantee_count'] ?? 0;
            $this->all_score       = $ret['vals']['all_score']       ?? 0;
            $this->all_free        = $ret['vals']['all_free']        ?? 0;
            $this->use             = $this->betGold * $this->betDouble * GAME_DOUBLE;

            if ($this->free) {
                $this->distime     = $ret['vals']['distime'];
                $this->free_get    = $ret['vals']['free_get'];
                $this->save_maps   = $ret['vals']['save_maps'];
                $this->freedistime = $ret['vals']['freedistime'];
            }
        }

        $this->map      = [];
        $this->deal_map = [];
        $this->resetCurResult();

        if ($this->free <= 0) {
            $this->free = 0;
            $this->normal_round_count = 0;
            $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
            $this->free_prize_level = 0;
            $this->free_total_limit_double = 30;
            $this->free_total_min_double = 0;
            $this->free_boom_left_count = 0;
            $this->free_boom_min_double = 0;
            $this->free_boom_max_double = 0;
            $this->free_boom_used = false;
        }

        $this->userInfo = $msg;
        $this->Msg_Game_RoomInfo(['uid' => $this->uid]);
    }

    public function DisRoom($msg = [])
    {
        $this->Msg_Game_Out(['uid' => $this->uid]);
    }

    // ================================================================
    // 退出/转账 (与主逻辑无关的基础设施)
    // ================================================================

    private function Msg_Game_Out($message)
    {
        Timer::del($this->mTimer);

        $gold = DBInstance::GetTableOneWord('user_register', 'gold', ['uid' => $this->uid]);
        $bank = DBInstance::GetTableOneWord('user_register', 'bank', ['uid' => $this->uid]);
        Logic::SendRight($this->uid, 'Msg_Game_Out', ['gold' => $gold, 'bank' => $bank]);

        $this->saveGameCache();

        $olddata = [
            'rid'     => $this->roomRule['rid'],
            'win'     => [],
            'palyers' => [$this->uid => $this->userInfo],
            'result'  => ['uid' => []],
            'gtype'   => $this->roomRule['gtype'],
        ];
        Logic::RoomOld($olddata);
    }

    public function ChangeGold($msg)
    {
        $uid = $msg['uid'];
        $before = DBInstance::GetUser(['uid' => $uid]);
        DBInstance::IncrementGolds('bank', $uid, $msg['data']['num']);
        DBInstance::InsertUserProfit($uid, $msg['data']['from'], $msg['data']['type'], $msg['data']['num'], $before);
        $data = DBInstance::GetTableWords('user_register', 'bank,gold', ['uid' => $uid]);
        $this->userInfo['bank'] = $data['bank'];
        Logic::SendRight($this->uid, 'Msg_Hall_ChangeGolds', $data);
    }

    public function BackTransfer($message)
    {
        $ret = DBInstance::BackTransfer($message['data']['out_id']);
        $uid = $message['uid'];
        $data = $message['data'];
        $user = DBInstance::GetTableWords('user_register', 'bank,gold', ['uid' => $uid]);

        $message['data'] = [
            'bank'   => $user['bank'],
            'gold'   => $user['gold'],
            'status' => $ret ? 0 : 2,
        ];
        Common::SendToClient($message, $data['client_id']);

        if ($ret) {
            $data = ['bank' => $user['bank'], 'gold' => $user['gold']];
            $this->userInfo['bank'] = $data['bank'];
            Logic::SendRight($this->uid, 'Msg_Hall_ChangeGolds', $data);
        }
    }

    // ================================================================
    // 主流程: 一局游戏开始
    // ================================================================

    private function Msg_MJHLT_Start($message)
    {
        // -------- 1. 参数与校验 --------
        $betLevelIndex = $message['data']['score'] * $message['data']['double'];
        if ($betLevelIndex <= 0) {
            Logic::SendError($message['uid'], $message['event'], '等级错误');
            return;
        }
        if (empty(Logic::$betLevel[$betLevelIndex])) {
            $levelValues = array_values(Logic::$betLevel);
            Logic::$betLevel[$betLevelIndex] = !empty($levelValues) ? min($levelValues) : 1;
        }

        $use = ($this->free <= 0) ? ($message['data']['score'] * $message['data']['double'] * GAME_DOUBLE) : 0;

        if ($message['uid'] != $this->uid || $this->userInfo['gold'] < $use) {
            Logic::SendError($message['uid'], $message['event'], '无效操作');
            return;
        }

        $betMin = $this->roomRule['bet_min'] ?? 10000;
        $betMax = $this->roomRule['bet_max'] ?? 200000;
        if ($this->free <= 0 && ($use < $betMin || $use > $betMax)) {
            Logic::SendError($message['uid'], $message['event'], '投注金额超出范围');
            return;
        }

        // -------- 2. 免费档位与下注状态初始化 --------
        $this->prepareBetState($message['data']['score'], $message['data']['double'], $use);

        // -------- 3. 控制表读取 --------
        $logo_num = DBInstance::GetControlMap($this->uid, $this->roomRule['gtype'], $this->roomRule['level']);
        $level_index = $this->betGold * $this->betDouble;
        $control = $logo_num ? -2 : DBInstance::GetLBControl($this->uid, $this->roomRule['gtype'], Logic::$betLevel[$level_index]);
        $control_map = DBInstance::GetControlInfo('control_mjhlt', ['level' => $control]);

        $this->buildMapPossible($control, $control_map);

        // -------- 4. 免费下一转倒计时 --------
        if ($control >= 0) {
            $this->next_free_count--;
        }
        if (
            (isset($control_map[$control]['free_cirle']) && $this->next_free_count > $control_map[$control]['free_cirle'])
            || $use <= 0
            || $control < 0
        ) {
            $this->next_free_count = max($control_map[$control]['free_cirle'] ?? 0, 50);
        }

        // -------- 5. 免费轮参数 --------
        $is_free_round = ($this->free > 0 && $this->use > 0);
        $freeParams = $this->buildFreeRoundParams($is_free_round);

        // -------- 6. 生成地图 (最多 loop_max 次重摇) --------
        $loop_max = $this->calcLoopMax($is_free_round, $freeParams);
        $best = $this->rollMapLoop($loop_max, $is_free_round, $freeParams, $logo_num, $control);

        // 若爆奖模式未找到合格地图, 使用最佳结果兜底
        if ($is_free_round && $freeParams['need_boost'] && !$best['valid_found'] && $best['best_result'] !== null) {
            $this->map       = $best['best_map'];
            $this->deal_map  = $best['best_deal_map'];
            $this->cur_result= $best['best_result'];
            if ($freeParams['is_boom_round']) {
                $this->free_boom_used = true;
            }
        }

        // -------- 7. 兜底: 若最终结果仍超出限制, 清空本轮 --------
        $this->finalizeCurResult($is_free_round, $freeParams);

        // -------- 8. 结算新免费局 (进入新免费游戏时设置档位) --------
        if ($this->cur_result['getfree'] > 0 && $this->free <= 0) {
            $this->initFreePrizeLevel();
        }

        // -------- 9. 扣金币 / 发奖 / 写库 --------
        if ($this->free > 0) {
            $this->free--;
        }
        $this->free      += $this->cur_result['getfree'];
        $this->all_free  += $this->cur_result['getfree'];

        $user_win = array_sum($this->cur_result['score']);
        $this->all_win += $user_win - $use;
        $this->useGold($user_win - $use);

        Common::SyncPlatformPlayGame($this->uid, $use, $user_win, $this->roomRule['app_rid'] ?? '');

        $latest = DBInstance::GetTableWords('user_register', 'gold', ['uid' => $this->uid]);
        if ($latest && isset($latest['gold'])) {
            $this->userInfo['gold'] = $latest['gold'];
        }

        // 大奖评级
        $reward = 0;
        foreach (BIG_WIN as $key => $value) {
            if (intval($user_win / $this->use) >= $value) {
                $reward = $key;
                break;
            }
        }

        $this->all_score += $user_win;

        // -------- 10. 下发 --------
        $data = [
            'disappear'  => $this->cur_result['disappear'],
            'score'      => $this->cur_result['score'],
            'logo_info'  => $this->cur_result['logo_info'],
            'cur_gold'   => $this->cur_result['cur_gold'],
            'cur_time'   => $this->cur_result['cur_time'],
            'double_arr' => $this->cur_result['double_arr'],
            'free_logo'  => $this->cur_result['free_logo'],
            'curgrade'   => $this->betGold,
            'curdouble'  => $this->betDouble,
            'conscore'   => $use,
            'map'        => $this->map,
            'free'       => $this->free,
            'getfree'    => $this->cur_result['getfree'],
            'reward'     => $reward,
            'user_gold'  => $this->userInfo['gold'],
            'all_score'  => $this->all_score,
        ];

        $record_data = [
            'score'      => $this->cur_result['score'],
            'cur_gold'   => $this->cur_result['cur_gold'],
            'cur_time'   => $this->cur_result['cur_time'],
            'free_logo'  => $this->cur_result['free_logo'],
            'curgrade'   => $this->betGold,
            'curdouble'  => $this->betDouble,
            'conscore'   => $use,
            'free'       => $this->free,
            'getfree'    => $this->cur_result['getfree'],
            'reward'     => $reward,
            'all_score'  => $this->all_score,
        ];
        $this->save_maps[] = $record_data;

        // -------- 11. 免费保底计数 --------
        $this->updateGuaranteeState($use);

        Logic::SendRight($this->uid, 'Msg_MJHLT_Start', $data);

        // -------- 12. 后台统计 --------
        DBInstance::IncrementUserGet($this->uid, $user_win - $use);

        if (abs($control) != 2) {
            Logic::InsertProfit(Logic::$betLevel[$level_index], $user_win - $use);
        }

        if ($use) {
            $this->distime = count($this->map) - 1;
            $this->free_get = 0;
            $this->freedistime = 0;
        } else {
            $this->free_get += $user_win;
            $this->freedistime += count($this->map) - 1;
        }

        if ($this->free <= 0) {
            DBInstance::InsertGameRecord(
                $this->roomRule['gtype'],
                $this->roomRule['level'],
                $this->uid,
                $this->use,
                ($this->all_score - $this->use),
                $this->distime,
                $this->all_free,
                $this->save_maps,
                $this->freedistime
            );
        }

        $double = intval($user_win / $this->use);
        if ($user_win > HORSE['score'] && $double >= HORSE['double']) {
            Logic::HorseLamp($this->uid, $user_win, $double);
        }
    }

    // ================================================================
    // 子方法：Msg_MJHLT_Start 的拆解
    // ================================================================

    /**
     * 下注/免费状态准备
     */
    private function prepareBetState($new_bet_gold, $new_bet_double, $use)
    {
        if ($this->free > 0) {
            // 免费中: 不改动任何下注状态, 沿用进入免费时的档位
            return;
        }

        $this->all_score = 0;
        $this->all_free  = 0;
        $this->save_maps = [];

        // 注档变化时重置免费保底进度 (防止低注刷保底再跳高注)
        if (
            ($this->guarantee_bet_gold > 0 || $this->guarantee_bet_double > 0)
            && ($this->guarantee_bet_gold != $new_bet_gold || $this->guarantee_bet_double != $new_bet_double)
        ) {
            $this->normal_round_count = 0;
            $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
            $this->is_free_guarantee = false;
        }

        $this->guarantee_bet_gold = $new_bet_gold;
        $this->guarantee_bet_double = $new_bet_double;
        $this->betGold   = $new_bet_gold;
        $this->betDouble = $new_bet_double;
        $this->use = $new_bet_gold * $new_bet_double * GAME_DOUBLE;
    }

    /**
     * 根据控制表构造 mapPossible / wildPossible
     */
    private function buildMapPossible($control, $control_map)
    {
        $this->mapPossible  = [];
        $this->wildPossible = [];

        if ($this->free > 0 && !empty($control_map[$control]['free_map']) && is_array($control_map[$control]['free_map'])) {
            $this->mapPossible = $control_map[$control]['free_map'];
            for ($i = 0; $i < 5; $i++) {
                $this->wildPossible[$i] = ($i && isset($control_map[$control]['free_wild'])) ? $control_map[$control]['free_wild'][$i] : 0;
            }
        } elseif (empty($control_map[$control]) || !is_array($control_map[$control]['map'])) {
            for ($i = 0; $i < 5; $i++) {
                $this->mapPossible[$i]  = POSSIBLE;
                $this->wildPossible[$i] = mt_rand(1, 6) ? 20 : 0;
            }
        } else {
            $this->mapPossible = $control_map[$control]['map'];
            for ($i = 0; $i < 5; $i++) {
                $this->wildPossible[$i] = ($i && isset($control_map[$control]['wild'])) ? $control_map[$control]['wild'][$i] : 0;
            }
        }
    }

    /**
     * 免费轮参数构造
     */
    private function buildFreeRoundParams($is_free_round)
    {
        $params = [
            'max_score'        => PHP_INT_MAX,
            'total_max_score'  => PHP_INT_MAX,
            'total_left_score' => PHP_INT_MAX,
            'reroll_min_score' => 0,
            'total_min_score'  => 0,
            'total_need_score' => 0,
            'need_boost'       => false,
            'boost_min_score'  => 0,
            'boost_max_score'  => PHP_INT_MAX,
            'is_boom_round'    => false,
        ];

        if (!$is_free_round) {
            return $params;
        }

        // 进入免费时的档位设置
        if ($this->free_prize_level == FREE_LEVEL_NORMAL) {
            $max_double       = 15;
            $reroll_min_double = 2;
        } elseif ($this->free_prize_level == FREE_LEVEL_BIG) {
            $max_double       = 130;
            $reroll_min_double = 20;
        } else {
            $max_double       = 300;
            $reroll_min_double = 80;
        }

        $params['max_score']       = $this->use * $max_double;
        $params['total_max_score'] = $this->use * $this->free_total_limit_double;
        $params['total_left_score']= max(0, $params['total_max_score'] - $this->free_get);
        $params['reroll_min_score']= $this->use * $reroll_min_double;
        $params['total_min_score'] = $this->use * $this->free_total_min_double;
        $params['total_need_score']= max(0, $params['total_min_score'] - $this->free_get);

        // 当前这转是不是指定的爆奖转?
        if (!$this->free_boom_used && $this->free_boom_left_count > 0 && $this->free == $this->free_boom_left_count) {
<?php

date_default_timezone_set('Asia/Shanghai');

use Workerman\Lib\Timer;

// ==================== 常量定义 ====================

define('ERTONG', 1);
define('ERTIAO', 2);
define('WUTONG', 3);
define('WUTIAO', 4);
define('BAWAN', 5);
define('BAIBAN', 6);
define('HONGZHONG', 7);
define('FACAI', 8);
define('SANTONG', 9);
define('FREE', 10);
define('BAIDA', 11);
define('GAME_DOUBLE', 20);

// 控制逻辑中引用的外部常量
defined('MAX_WIN_SCORE') || define('MAX_WIN_SCORE', 1000000);

// 不同图案连击的赔付倍率表 (3连/4连/5连)
define('DOUBLE', [
    ERTONG    => [3 => 1,  4 => 3,   5 => 6],
    ERTIAO    => [3 => 1,  4 => 3,   5 => 6],
    SANTONG   => [3 => 2,  4 => 4,   5 => 10],
    WUTONG    => [3 => 3,  4 => 5,   5 => 12],
    WUTIAO    => [3 => 3,  4 => 5,   5 => 12],
    BAWAN     => [3 => 5,  4 => 10,  5 => 15],
    BAIBAN    => [3 => 6,  4 => 15,  5 => 30],
    HONGZHONG => [3 => 8,  4 => 20,  5 => 40],
    FACAI     => [3 => 10, 4 => 25,  5 => 50],
]);

// 图案出现概率 (普通地图 / 免费地图)
define('POSSIBLE',      [ERTONG => 50, ERTIAO => 50, SANTONG => 50, WUTONG => 30, WUTIAO => 30, BAWAN => 15, BAIBAN => 7,  HONGZHONG => 3, FACAI => 1, FREE => 200]);
define('FREEPOSSIBLE',  [ERTONG => 50, ERTIAO => 50, SANTONG => 50, WUTONG => 30, WUTIAO => 30, BAWAN => 10, BAIBAN => 3,  HONGZHONG => 2, FACAI => 1, FREE => 8]);

// 大奖评级 (3=大/2=中/1=小)
define('BIG_WIN', [3 => 40, 2 => 20, 1 => 10]);

// Wild 柱阈值 (万分之 N)
define('WILD_PERCENT', 5000);

// 跑马灯触发条件
define('HORSE', ['double' => 20, 'score' => 1]);

// 免费游戏档位
define('FREE_LEVEL_NORMAL', 0);   // 普通
define('FREE_LEVEL_BIG',    1);   // 大奖/超级
define('FREE_LEVEL_JACKPOT',2);   // 爆奖


/**
 * 麻将/老虎机游戏主逻辑
 */
class Table
{
    // ==================== 玩家状态 ====================
    private $userInfo = [];
    private $uid = 0;
    private $free = 0;             // 剩余免费次数
    private $map = [];             // 地图 (各轮)
    private $betGold = 0;          // 当前下注档位
    private $betDouble = 1;        // 当前下注倍率
    private $roomRule = [];        // 房间配置
    private $use = 0;              // 实际消耗金币
    private $mTimer = 0;
    private $mapPossible = [];     // 当前地图概率表 (5列)
    private $wildPossible = [];    // Wild 出现概率 (5列)

    // ==================== 单局结算 ====================
    private $cur_result = [];
    private $deal_map = [];
    private $all_score = 0;        // 整局总得分
    private $all_free = 0;         // 整局获得的免费次数
    private $free_get = 0;         // 免费轮累计得分
    private $save_maps = [];
    private $distime = 0;
    private $freedistime = 0;
    private $next_free_count = 999;

    // ==================== 免费保底 ====================
    private $normal_round_count = 0;
    private $free_guarantee_threshold = 0;
    private $is_free_guarantee = false;
    private $free_guarantee_min = 150;
    private $free_guarantee_max = 250;

    // ==================== 免费游戏档位 ====================
    private $free_total_limit_double = 30;
    private $free_total_min_double = 0;
    private $free_prize_level = 0;
    private $force_free_trigger = false;

    private $free_boom_left_count = 0;   // 爆奖在剩余第几转出现
    private $free_boom_min_double = 0;
    private $free_boom_max_double = 0;
    private $free_boom_used = false;

    private $guarantee_bet_gold = 0;
    private $guarantee_bet_double = 0;
    private $guarantee_count = 0;

    // ==================== 胜负统计 ====================
    private $all_win = 0;


    // ================================================================
    // 构造与入口
    // ================================================================

    public function __construct($msg)
    {
        $this->roomRule = $msg;
        $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
        $this->resetCurResult();
    }

    public function All_RECV($message)
    {
        switch ($message['event']) {
            case 'Msg_MJHLT_Start':
                $this->Msg_MJHLT_Start($message);
                break;
            case 'Msg_Game_Out':
                $this->Msg_Game_Out($message);
                break;
            case 'Msg_Game_RoomInfo':
                $this->Msg_Game_RoomInfo($message);
                break;
            default:
                Logic::SendError($message['uid'], $message['event'], '');
                MyTools::msg('uid:' . $message['uid'] . '-----UnKnown!!!!!!!--------' . $message['event'], true);
                break;
        }
    }

    // ================================================================
    // 房间信息 / 进房 / 离线
    // ================================================================

    private function Msg_Game_RoomInfo($message)
    {
        if ($this->uid && $this->uid == $message['uid']) {
            Logic::SendRight($this->uid, 'Msg_Game_RoomInfo', [
                'free'         => $this->free,
                'all_score'    => $this->all_score,
                'all_free'     => $this->all_free,
                'curgrade'     => $this->betGold,
                'curdouble'    => $this->betDouble,
                'map'          => $this->map,
                'max_multiple' => max($this->roomRule['score_arr']),
                'level'        => $this->roomRule['level'],
                'score_arr'    => $this->roomRule['score_arr'],
                'double_arr'   => $this->roomRule['double_arr'],
                'base_arr'     => [GAME_DOUBLE],
                'min_gold'     => $this->roomRule['min_gold'],
                'max_gold'     => $this->roomRule['max_gold'],
                'bet_min'      => $this->roomRule['bet_min'] ?? 10000,
                'bet_max'      => $this->roomRule['bet_max'] ?? 200000,
                'gold'         => $this->userInfo['gold'],
            ]);
        } else {
            Logic::SendError($message['uid'], 'Msg_Game_RoomInfo', '无效操作');
        }
    }

    public function UserOnline($client_id, $uid)
    {
        Timer::del($this->mTimer);
        $this->Msg_Game_RoomInfo(['uid' => $uid]);
    }

    public function UserOff($uid)
    {
        $this->saveGameCache();
        $this->mTimer = Timer::add(60, function () {
            $this->Msg_Game_Out(['uid' => $this->uid]);
        }, [], false);
    }

    public function EnterRoom($msg)
    {
        $this->uid = $msg['uid'];
        $ret = DBInstance::GetGameCache($this->uid, $this->roomRule['gtype'], $this->roomRule['level']);

        if (!$ret) {
            $this->betGold   = min($this->roomRule['score_arr']);
            $this->betDouble = min($this->roomRule['double_arr']);
            DBInstance::InsertGameCache([
                'uid'        => $this->uid,
                'gtype'      => $this->roomRule['gtype'],
                'level'      => $this->roomRule['level'],
                'map'        => '[]',
                'bet_gold'   => $this->betGold,
                'bet_double' => $this->betDouble,
                'free'       => 0,
            ]);
            $this->guarantee_count = 0;
        } else {
            $this->map  = $ret['map'];
            $this->free = $ret['free'];

            if ($this->free > 0) {
                $this->betGold   = $ret['bet_gold'];
                $this->betDouble = $ret['bet_double'];
            } else {
                $this->betGold   = min($this->roomRule['score_arr']);
                $this->betDouble = min($this->roomRule['double_arr']);
            }

            $this->guarantee_count = $ret['vals']['guarantee_count'] ?? 0;
            $this->all_score       = $ret['vals']['all_score']       ?? 0;
            $this->all_free        = $ret['vals']['all_free']        ?? 0;
            $this->use             = $this->betGold * $this->betDouble * GAME_DOUBLE;

            if ($this->free) {
                $this->distime     = $ret['vals']['distime'];
                $this->free_get    = $ret['vals']['free_get'];
                $this->save_maps   = $ret['vals']['save_maps'];
                $this->freedistime = $ret['vals']['freedistime'];
            }
        }

        $this->map      = [];
        $this->deal_map = [];
        $this->resetCurResult();

        if ($this->free <= 0) {
            $this->free = 0;
            $this->normal_round_count = 0;
            $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
            $this->free_prize_level = 0;
            $this->free_total_limit_double = 30;
            $this->free_total_min_double = 0;
            $this->free_boom_left_count = 0;
            $this->free_boom_min_double = 0;
            $this->free_boom_max_double = 0;
            $this->free_boom_used = false;
        }

        $this->userInfo = $msg;
        $this->Msg_Game_RoomInfo(['uid' => $this->uid]);
    }

    public function DisRoom($msg = [])
    {
        $this->Msg_Game_Out(['uid' => $this->uid]);
    }

    // ================================================================
    // 退出/转账 (与主逻辑无关的基础设施)
    // ================================================================

    private function Msg_Game_Out($message)
    {
        Timer::del($this->mTimer);

        $gold = DBInstance::GetTableOneWord('user_register', 'gold', ['uid' => $this->uid]);
        $bank = DBInstance::GetTableOneWord('user_register', 'bank', ['uid' => $this->uid]);
        Logic::SendRight($this->uid, 'Msg_Game_Out', ['gold' => $gold, 'bank' => $bank]);

        $this->saveGameCache();

        $olddata = [
            'rid'     => $this->roomRule['rid'],
            'win'     => [],
            'palyers' => [$this->uid => $this->userInfo],
            'result'  => ['uid' => []],
            'gtype'   => $this->roomRule['gtype'],
        ];
        Logic::RoomOld($olddata);
    }

    public function ChangeGold($msg)
    {
        $uid = $msg['uid'];
        $before = DBInstance::GetUser(['uid' => $uid]);
        DBInstance::IncrementGolds('bank', $uid, $msg['data']['num']);
        DBInstance::InsertUserProfit($uid, $msg['data']['from'], $msg['data']['type'], $msg['data']['num'], $before);
        $data = DBInstance::GetTableWords('user_register', 'bank,gold', ['uid' => $uid]);
        $this->userInfo['bank'] = $data['bank'];
        Logic::SendRight($this->uid, 'Msg_Hall_ChangeGolds', $data);
    }

    public function BackTransfer($message)
    {
        $ret = DBInstance::BackTransfer($message['data']['out_id']);
        $uid = $message['uid'];
        $data = $message['data'];
        $user = DBInstance::GetTableWords('user_register', 'bank,gold', ['uid' => $uid]);

        $message['data'] = [
            'bank'   => $user['bank'],
            'gold'   => $user['gold'],
            'status' => $ret ? 0 : 2,
        ];
        Common::SendToClient($message, $data['client_id']);

        if ($ret) {
            $data = ['bank' => $user['bank'], 'gold' => $user['gold']];
            $this->userInfo['bank'] = $data['bank'];
            Logic::SendRight($this->uid, 'Msg_Hall_ChangeGolds', $data);
        }
    }

    // ================================================================
    // 主流程: 一局游戏开始
    // ================================================================

    private function Msg_MJHLT_Start($message)
    {
        // -------- 1. 参数与校验 --------
        $betLevelIndex = $message['data']['score'] * $message['data']['double'];
        if ($betLevelIndex <= 0) {
            Logic::SendError($message['uid'], $message['event'], '等级错误');
            return;
        }
        if (empty(Logic::$betLevel[$betLevelIndex])) {
            $levelValues = array_values(Logic::$betLevel);
            Logic::$betLevel[$betLevelIndex] = !empty($levelValues) ? min($levelValues) : 1;
        }

        $use = ($this->free <= 0) ? ($message['data']['score'] * $message['data']['double'] * GAME_DOUBLE) : 0;

        if ($message['uid'] != $this->uid || $this->userInfo['gold'] < $use) {
            Logic::SendError($message['uid'], $message['event'], '无效操作');
            return;
        }

        $betMin = $this->roomRule['bet_min'] ?? 10000;
        $betMax = $this->roomRule['bet_max'] ?? 200000;
        if ($this->free <= 0 && ($use < $betMin || $use > $betMax)) {
            Logic::SendError($message['uid'], $message['event'], '投注金额超出范围');
            return;
        }

        // -------- 2. 免费档位与下注状态初始化 --------
        $this->prepareBetState($message['data']['score'], $message['data']['double'], $use);

        // -------- 3. 控制表读取 --------
        $logo_num = DBInstance::GetControlMap($this->uid, $this->roomRule['gtype'], $this->roomRule['level']);
        $level_index = $this->betGold * $this->betDouble;
        $control = $logo_num ? -2 : DBInstance::GetLBControl($this->uid, $this->roomRule['gtype'], Logic::$betLevel[$level_index]);
        $control_map = DBInstance::GetControlInfo('control_mjhlt', ['level' => $control]);

        $this->buildMapPossible($control, $control_map);

        // -------- 4. 免费下一转倒计时 --------
        if ($control >= 0) {
            $this->next_free_count--;
        }
        if (
            (isset($control_map[$control]['free_cirle']) && $this->next_free_count > $control_map[$control]['free_cirle'])
            || $use <= 0
            || $control < 0
        ) {
            $this->next_free_count = max($control_map[$control]['free_cirle'] ?? 0, 50);
        }

        // -------- 5. 免费轮参数 --------
        $is_free_round = ($this->free > 0 && $this->use > 0);
        $freeParams = $this->buildFreeRoundParams($is_free_round);

        // -------- 6. 生成地图 (最多 loop_max 次重摇) --------
        $loop_max = $this->calcLoopMax($is_free_round, $freeParams);
        $best = $this->rollMapLoop($loop_max, $is_free_round, $freeParams, $logo_num, $control);

        // 若爆奖模式未找到合格地图, 使用最佳结果兜底
        if ($is_free_round && $freeParams['need_boost'] && !$best['valid_found'] && $best['best_result'] !== null) {
            $this->map       = $best['best_map'];
            $this->deal_map  = $best['best_deal_map'];
            $this->cur_result= $best['best_result'];
            if ($freeParams['is_boom_round']) {
                $this->free_boom_used = true;
            }
        }

        // -------- 7. 兜底: 若最终结果仍超出限制, 清空本轮 --------
        $this->finalizeCurResult($is_free_round, $freeParams);

        // -------- 8. 结算新免费局 (进入新免费游戏时设置档位) --------
        if ($this->cur_result['getfree'] > 0 && $this->free <= 0) {
            $this->initFreePrizeLevel();
        }

        // -------- 9. 扣金币 / 发奖 / 写库 --------
        if ($this->free > 0) {
            $this->free--;
        }
        $this->free      += $this->cur_result['getfree'];
        $this->all_free  += $this->cur_result['getfree'];

        $user_win = array_sum($this->cur_result['score']);
        $this->all_win += $user_win - $use;
        $this->useGold($user_win - $use);

        Common::SyncPlatformPlayGame($this->uid, $use, $user_win, $this->roomRule['app_rid'] ?? '');

        $latest = DBInstance::GetTableWords('user_register', 'gold', ['uid' => $this->uid]);
        if ($latest && isset($latest['gold'])) {
            $this->userInfo['gold'] = $latest['gold'];
        }

        // 大奖评级
        $reward = 0;
        foreach (BIG_WIN as $key => $value) {
            if (intval($user_win / $this->use) >= $value) {
                $reward = $key;
                break;
            }
        }

        $this->all_score += $user_win;

        // -------- 10. 下发 --------
        $data = [
            'disappear'  => $this->cur_result['disappear'],
            'score'      => $this->cur_result['score'],
            'logo_info'  => $this->cur_result['logo_info'],
            'cur_gold'   => $this->cur_result['cur_gold'],
            'cur_time'   => $this->cur_result['cur_time'],
            'double_arr' => $this->cur_result['double_arr'],
            'free_logo'  => $this->cur_result['free_logo'],
            'curgrade'   => $this->betGold,
            'curdouble'  => $this->betDouble,
            'conscore'   => $use,
            'map'        => $this->map,
            'free'       => $this->free,
            'getfree'    => $this->cur_result['getfree'],
            'reward'     => $reward,
            'user_gold'  => $this->userInfo['gold'],
            'all_score'  => $this->all_score,
        ];

        $record_data = [
            'score'      => $this->cur_result['score'],
            'cur_gold'   => $this->cur_result['cur_gold'],
            'cur_time'   => $this->cur_result['cur_time'],
            'free_logo'  => $this->cur_result['free_logo'],
            'curgrade'   => $this->betGold,
            'curdouble'  => $this->betDouble,
            'conscore'   => $use,
            'free'       => $this->free,
            'getfree'    => $this->cur_result['getfree'],
            'reward'     => $reward,
            'all_score'  => $this->all_score,
        ];
        $this->save_maps[] = $record_data;

        // -------- 11. 免费保底计数 --------
        $this->updateGuaranteeState($use);

        Logic::SendRight($this->uid, 'Msg_MJHLT_Start', $data);

        // -------- 12. 后台统计 --------
        DBInstance::IncrementUserGet($this->uid, $user_win - $use);

        if (abs($control) != 2) {
            Logic::InsertProfit(Logic::$betLevel[$level_index], $user_win - $use);
        }

        if ($use) {
            $this->distime = count($this->map) - 1;
            $this->free_get = 0;
            $this->freedistime = 0;
        } else {
            $this->free_get += $user_win;
            $this->freedistime += count($this->map) - 1;
        }

        if ($this->free <= 0) {
            DBInstance::InsertGameRecord(
                $this->roomRule['gtype'],
                $this->roomRule['level'],
                $this->uid,
                $this->use,
                ($this->all_score - $this->use),
                $this->distime,
                $this->all_free,
                $this->save_maps,
                $this->freedistime
            );
        }

        $double = intval($user_win / $this->use);
        if ($user_win > HORSE['score'] && $double >= HORSE['double']) {
            Logic::HorseLamp($this->uid, $user_win, $double);
        }
    }

    // ================================================================
    // 子方法：Msg_MJHLT_Start 的拆解
    // ================================================================

    /**
     * 下注/免费状态准备
     */
    private function prepareBetState($new_bet_gold, $new_bet_double, $use)
    {
        if ($this->free > 0) {
            // 免费中: 不改动任何下注状态, 沿用进入免费时的档位
            return;
        }

        $this->all_score = 0;
        $this->all_free  = 0;
        $this->save_maps = [];

        // 注档变化时重置免费保底进度 (防止低注刷保底再跳高注)
        if (
            ($this->guarantee_bet_gold > 0 || $this->guarantee_bet_double > 0)
            && ($this->guarantee_bet_gold != $new_bet_gold || $this->guarantee_bet_double != $new_bet_double)
        ) {
            $this->normal_round_count = 0;
            $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
            $this->is_free_guarantee = false;
        }

        $this->guarantee_bet_gold = $new_bet_gold;
        $this->guarantee_bet_double = $new_bet_double;
        $this->betGold   = $new_bet_gold;
        $this->betDouble = $new_bet_double;
        $this->use = $new_bet_gold * $new_bet_double * GAME_DOUBLE;
    }

    /**
     * 根据控制表构造 mapPossible / wildPossible
     */
    private function buildMapPossible($control, $control_map)
    {
        $this->mapPossible  = [];
        $this->wildPossible = [];

        if ($this->free > 0 && !empty($control_map[$control]['free_map']) && is_array($control_map[$control]['free_map'])) {
            $this->mapPossible = $control_map[$control]['free_map'];
            for ($i = 0; $i < 5; $i++) {
                $this->wildPossible[$i] = ($i && isset($control_map[$control]['free_wild'])) ? $control_map[$control]['free_wild'][$i] : 0;
            }
        } elseif (empty($control_map[$control]) || !is_array($control_map[$control]['map'])) {
            for ($i = 0; $i < 5; $i++) {
                $this->mapPossible[$i]  = POSSIBLE;
                $this->wildPossible[$i] = mt_rand(1, 6) ? 20 : 0;
            }
        } else {
            $this->mapPossible = $control_map[$control]['map'];
            for ($i = 0; $i < 5; $i++) {
                $this->wildPossible[$i] = ($i && isset($control_map[$control]['wild'])) ? $control_map[$control]['wild'][$i] : 0;
            }
        }
    }

    /**
     * 免费轮参数构造
     */
    private function buildFreeRoundParams($is_free_round)
    {
        $params = [
            'max_score'        => PHP_INT_MAX,
            'total_max_score'  => PHP_INT_MAX,
            'total_left_score' => PHP_INT_MAX,
            'reroll_min_score' => 0,
            'total_min_score'  => 0,
            'total_need_score' => 0,
            'need_boost'       => false,
            'boost_min_score'  => 0,
            'boost_max_score'  => PHP_INT_MAX,
            'is_boom_round'    => false,
        ];

        if (!$is_free_round) {
            return $params;
        }

        // 进入免费时的档位设置
        if ($this->free_prize_level == FREE_LEVEL_NORMAL) {
            $max_double       = 15;
            $reroll_min_double = 2;
        } elseif ($this->free_prize_level == FREE_LEVEL_BIG) {
            $max_double       = 130;
            $reroll_min_double = 20;
        } else {
            $max_double       = 300;
            $reroll_min_double = 80;
        }

        $params['max_score']       = $this->use * $max_double;
        $params['total_max_score'] = $this->use * $this->free_total_limit_double;
        $params['total_left_score']= max(0, $params['total_max_score'] - $this->free_get);
        $params['reroll_min_score']= $this->use * $reroll_min_double;
        $params['total_min_score'] = $this->use * $this->free_total_min_double;
        $params['total_need_score']= max(0, $params['total_min_score'] - $this->free_get);

        // 当前这转是不是指定的爆奖转?
        if (!$this->free_boom_used && $this->free_boom_left_count > 0 && $this->free == $this->free_boom_left_count) {
            $params['is_boom_round']   = true;
            $params['need_boost<?php

date_default_timezone_set('Asia/Shanghai');

use Workerman\Lib\Timer;

// ==================== 常量定义 ====================

define('ERTONG', 1);
define('ERTIAO', 2);
define('WUTONG', 3);
define('WUTIAO', 4);
define('BAWAN', 5);
define('BAIBAN', 6);
define('HONGZHONG', 7);
define('FACAI', 8);
define('SANTONG', 9);
define('FREE', 10);
define('BAIDA', 11);
define('GAME_DOUBLE', 20);

// 控制逻辑中引用的外部常量
defined('MAX_WIN_SCORE') || define('MAX_WIN_SCORE', 1000000);

// 不同图案连击的赔付倍率表 (3连/4连/5连)
define('DOUBLE', [
    ERTONG    => [3 => 1,  4 => 3,   5 => 6],
    ERTIAO    => [3 => 1,  4 => 3,   5 => 6],
    SANTONG   => [3 => 2,  4 => 4,   5 => 10],
    WUTONG    => [3 => 3,  4 => 5,   5 => 12],
    WUTIAO    => [3 => 3,  4 => 5,   5 => 12],
    BAWAN     => [3 => 5,  4 => 10,  5 => 15],
    BAIBAN    => [3 => 6,  4 => 15,  5 => 30],
    HONGZHONG => [3 => 8,  4 => 20,  5 => 40],
    FACAI     => [3 => 10, 4 => 25,  5 => 50],
]);

// 图案出现概率 (普通地图 / 免费地图)
define('POSSIBLE',      [ERTONG => 50, ERTIAO => 50, SANTONG => 50, WUTONG => 30, WUTIAO => 30, BAWAN => 15, BAIBAN => 7,  HONGZHONG => 3, FACAI => 1, FREE => 200]);
define('FREEPOSSIBLE',  [ERTONG => 50, ERTIAO => 50, SANTONG => 50, WUTONG => 30, WUTIAO => 30, BAWAN => 10, BAIBAN => 3,  HONGZHONG => 2, FACAI => 1, FREE => 8]);

// 大奖评级 (3=大/2=中/1=小)
define('BIG_WIN', [3 => 40, 2 => 20, 1 => 10]);

// Wild 柱阈值 (万分之 N)
define('WILD_PERCENT', 5000);

// 跑马灯触发条件
define('HORSE', ['double' => 20, 'score' => 1]);

// 免费游戏档位
define('FREE_LEVEL_NORMAL', 0);   // 普通
define('FREE_LEVEL_BIG',    1);   // 大奖/超级
define('FREE_LEVEL_JACKPOT',2);   // 爆奖


/**
 * 麻将/老虎机游戏主逻辑
 */
class Table
{
    // ==================== 玩家状态 ====================
    private $userInfo = [];
    private $uid = 0;
    private $free = 0;             // 剩余免费次数
    private $map = [];             // 地图 (各轮)
    private $betGold = 0;          // 当前下注档位
    private $betDouble = 1;        // 当前下注倍率
    private $roomRule = [];        // 房间配置
    private $use = 0;              // 实际消耗金币
    private $mTimer = 0;
    private $mapPossible = [];     // 当前地图概率表 (5列)
    private $wildPossible = [];    // Wild 出现概率 (5列)

    // ==================== 单局结算 ====================
    private $cur_result = [];
    private $deal_map = [];
    private $all_score = 0;        // 整局总得分
    private $all_free = 0;         // 整局获得的免费次数
    private $free_get = 0;         // 免费轮累计得分
    private $save_maps = [];
    private $distime = 0;
    private $freedistime = 0;
    private $next_free_count = 999;

    // ==================== 免费保底 ====================
    private $normal_round_count = 0;
    private $free_guarantee_threshold = 0;
    private $is_free_guarantee = false;
    private $free_guarantee_min = 150;
    private $free_guarantee_max = 250;

    // ==================== 免费游戏档位 ====================
    private $free_total_limit_double = 30;
    private $free_total_min_double = 0;
    private $free_prize_level = 0;
    private $force_free_trigger = false;

    private $free_boom_left_count = 0;   // 爆奖在剩余第几转出现
    private $free_boom_min_double = 0;
    private $free_boom_max_double = 0;
    private $free_boom_used = false;

    private $guarantee_bet_gold = 0;
    private $guarantee_bet_double = 0;
    private $guarantee_count = 0;

    // ==================== 胜负统计 ====================
    private $all_win = 0;


    // ================================================================
    // 构造与入口
    // ================================================================

    public function __construct($msg)
    {
        $this->roomRule = $msg;
        $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
        $this->resetCurResult();
    }

    public function All_RECV($message)
    {
        switch ($message['event']) {
            case 'Msg_MJHLT_Start':
                $this->Msg_MJHLT_Start($message);
                break;
            case 'Msg_Game_Out':
                $this->Msg_Game_Out($message);
                break;
            case 'Msg_Game_RoomInfo':
                $this->Msg_Game_RoomInfo($message);
                break;
            default:
                Logic::SendError($message['uid'], $message['event'], '');
                MyTools::msg('uid:' . $message['uid'] . '-----UnKnown!!!!!!!--------' . $message['event'], true);
                break;
        }
    }

    // ================================================================
    // 房间信息 / 进房 / 离线
    // ================================================================

    private function Msg_Game_RoomInfo($message)
    {
        if ($this->uid && $this->uid == $message['uid']) {
            Logic::SendRight($this->uid, 'Msg_Game_RoomInfo', [
                'free'         => $this->free,
                'all_score'    => $this->all_score,
                'all_free'     => $this->all_free,
                'curgrade'     => $this->betGold,
                'curdouble'    => $this->betDouble,
                'map'          => $this->map,
                'max_multiple' => max($this->roomRule['score_arr']),
                'level'        => $this->roomRule['level'],
                'score_arr'    => $this->roomRule['score_arr'],
                'double_arr'   => $this->roomRule['double_arr'],
                'base_arr'     => [GAME_DOUBLE],
                'min_gold'     => $this->roomRule['min_gold'],
                'max_gold'     => $this->roomRule['max_gold'],
                'bet_min'      => $this->roomRule['bet_min'] ?? 10000,
                'bet_max'      => $this->roomRule['bet_max'] ?? 200000,
                'gold'         => $this->userInfo['gold'],
            ]);
        } else {
            Logic::SendError($message['uid'], 'Msg_Game_RoomInfo', '无效操作');
        }
    }

    public function UserOnline($client_id, $uid)
    {
        Timer::del($this->mTimer);
        $this->Msg_Game_RoomInfo(['uid' => $uid]);
    }

    public function UserOff($uid)
    {
        $this->saveGameCache();
        $this->mTimer = Timer::add(60, function () {
            $this->Msg_Game_Out(['uid' => $this->uid]);
        }, [], false);
    }

    public function EnterRoom($msg)
    {
        $this->uid = $msg['uid'];
        $ret = DBInstance::GetGameCache($this->uid, $this->roomRule['gtype'], $this->roomRule['level']);

        if (!$ret) {
            $this->betGold   = min($this->roomRule['score_arr']);
            $this->betDouble = min($this->roomRule['double_arr']);
            DBInstance::InsertGameCache([
                'uid'        => $this->uid,
                'gtype'      => $this->roomRule['gtype'],
                'level'      => $this->roomRule['level'],
                'map'        => '[]',
                'bet_gold'   => $this->betGold,
                'bet_double' => $this->betDouble,
                'free'       => 0,
            ]);
            $this->guarantee_count = 0;
        } else {
            $this->map  = $ret['map'];
            $this->free = $ret['free'];

            if ($this->free > 0) {
                $this->betGold   = $ret['bet_gold'];
                $this->betDouble = $ret['bet_double'];
            } else {
                $this->betGold   = min($this->roomRule['score_arr']);
                $this->betDouble = min($this->roomRule['double_arr']);
            }

            $this->guarantee_count = $ret['vals']['guarantee_count'] ?? 0;
            $this->all_score       = $ret['vals']['all_score']       ?? 0;
            $this->all_free        = $ret['vals']['all_free']        ?? 0;
            $this->use             = $this->betGold * $this->betDouble * GAME_DOUBLE;

            if ($this->free) {
                $this->distime     = $ret['vals']['distime'];
                $this->free_get    = $ret['vals']['free_get'];
                $this->save_maps   = $ret['vals']['save_maps'];
                $this->freedistime = $ret['vals']['freedistime'];
            }
        }

        $this->map      = [];
        $this->deal_map = [];
        $this->resetCurResult();

        if ($this->free <= 0) {
            $this->free = 0;
            $this->normal_round_count = 0;
            $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
            $this->free_prize_level = 0;
            $this->free_total_limit_double = 30;
            $this->free_total_min_double = 0;
            $this->free_boom_left_count = 0;
            $this->free_boom_min_double = 0;
            $this->free_boom_max_double = 0;
            $this->free_boom_used = false;
        }

        $this->userInfo = $msg;
        $this->Msg_Game_RoomInfo(['uid' => $this->uid]);
    }

    public function DisRoom($msg = [])
    {
        $this->Msg_Game_Out(['uid' => $this->uid]);
    }

    // ================================================================
    // 退出/转账 (与主逻辑无关的基础设施)
    // ================================================================

    private function Msg_Game_Out($message)
    {
        Timer::del($this->mTimer);

        $gold = DBInstance::GetTableOneWord('user_register', 'gold', ['uid' => $this->uid]);
        $bank = DBInstance::GetTableOneWord('user_register', 'bank', ['uid' => $this->uid]);
        Logic::SendRight($this->uid, 'Msg_Game_Out', ['gold' => $gold, 'bank' => $bank]);

        $this->saveGameCache();

        $olddata = [
            'rid'     => $this->roomRule['rid'],
            'win'     => [],
            'palyers' => [$this->uid => $this->userInfo],
            'result'  => ['uid' => []],
            'gtype'   => $this->roomRule['gtype'],
        ];
        Logic::RoomOld($olddata);
    }

    public function ChangeGold($msg)
    {
        $uid = $msg['uid'];
        $before = DBInstance::GetUser(['uid' => $uid]);
        DBInstance::IncrementGolds('bank', $uid, $msg['data']['num']);
        DBInstance::InsertUserProfit($uid, $msg['data']['from'], $msg['data']['type'], $msg['data']['num'], $before);
        $data = DBInstance::GetTableWords('user_register', 'bank,gold', ['uid' => $uid]);
        $this->userInfo['bank'] = $data['bank'];
        Logic::SendRight($this->uid, 'Msg_Hall_ChangeGolds', $data);
    }

    public function BackTransfer($message)
    {
        $ret = DBInstance::BackTransfer($message['data']['out_id']);
        $uid = $message['uid'];
        $data = $message['data'];
        $user = DBInstance::GetTableWords('user_register', 'bank,gold', ['uid' => $uid]);

        $message['data'] = [
            'bank'   => $user['bank'],
            'gold'   => $user['gold'],
            'status' => $ret ? 0 : 2,
        ];
        Common::SendToClient($message, $data['client_id']);

        if ($ret) {
            $data = ['bank' => $user['bank'], 'gold' => $user['gold']];
            $this->userInfo['bank'] = $data['bank'];
            Logic::SendRight($this->uid, 'Msg_Hall_ChangeGolds', $data);
        }
    }

    // ================================================================
    // 主流程: 一局游戏开始
    // ================================================================

    private function Msg_MJHLT_Start($message)
    {
        // -------- 1. 参数与校验 --------
        $betLevelIndex = $message['data']['score'] * $message['data']['double'];
        if ($betLevelIndex <= 0) {
            Logic::SendError($message['uid'], $message['event'], '等级错误');
            return;
        }
        if (empty(Logic::$betLevel[$betLevelIndex])) {
            $levelValues = array_values(Logic::$betLevel);
            Logic::$betLevel[$betLevelIndex] = !empty($levelValues) ? min($levelValues) : 1;
        }

        $use = ($this->free <= 0) ? ($message['data']['score'] * $message['data']['double'] * GAME_DOUBLE) : 0;

        if ($message['uid'] != $this->uid || $this->userInfo['gold'] < $use) {
            Logic::SendError($message['uid'], $message['event'], '无效操作');
            return;
        }

        $betMin = $this->roomRule['bet_min'] ?? 10000;
        $betMax = $this->roomRule['bet_max'] ?? 200000;
        if ($this->free <= 0 && ($use < $betMin || $use > $betMax)) {
            Logic::SendError($message['uid'], $message['event'], '投注金额超出范围');
            return;
        }

        // -------- 2. 免费档位与下注状态初始化 --------
        $this->prepareBetState($message['data']['score'], $message['data']['double'], $use);

        // -------- 3. 控制表读取 --------
        $logo_num = DBInstance::GetControlMap($this->uid, $this->roomRule['gtype'], $this->roomRule['level']);
        $level_index = $this->betGold * $this->betDouble;
        $control = $logo_num ? -2 : DBInstance::GetLBControl($this->uid, $this->roomRule['gtype'], Logic::$betLevel[$level_index]);
        $control_map = DBInstance::GetControlInfo('control_mjhlt', ['level' => $control]);

        $this->buildMapPossible($control, $control_map);

        // -------- 4. 免费下一转倒计时 --------
        if ($control >= 0) {
            $this->next_free_count--;
        }
        if (
            (isset($control_map[$control]['free_cirle']) && $this->next_free_count > $control_map[$control]['free_cirle'])
            || $use <= 0
            || $control < 0
        ) {
            $this->next_free_count = max($control_map[$control]['free_cirle'] ?? 0, 50);
        }

        // -------- 5. 免费轮参数 --------
        $is_free_round = ($this->free > 0 && $this->use > 0);
        $freeParams = $this->buildFreeRoundParams($is_free_round);

        // -------- 6. 生成地图 (最多 loop_max 次重摇) --------
        $loop_max = $this->calcLoopMax($is_free_round, $freeParams);
        $best = $this->rollMapLoop($loop_max, $is_free_round, $freeParams, $logo_num, $control);

        // 若爆奖模式未找到合格地图, 使用最佳结果兜底
        if ($is_free_round && $freeParams['need_boost'] && !$best['valid_found'] && $best['best_result'] !== null) {
            $this->map       = $best['best_map'];
            $this->deal_map  = $best['best_deal_map'];
            $this->cur_result= $best['best_result'];
            if ($freeParams['is_boom_round']) {
                $this->free_boom_used = true;
            }
        }

        // -------- 7. 兜底: 若最终结果仍超出限制, 清空本轮 --------
        $this->finalizeCurResult($is_free_round, $freeParams);

        // -------- 8. 结算新免费局 (进入新免费游戏时设置档位) --------
        if ($this->cur_result['getfree'] > 0 && $this->free <= 0) {
            $this->initFreePrizeLevel();
        }

        // -------- 9. 扣金币 / 发奖 / 写库 --------
        if ($this->free > 0) {
            $this->free--;
        }
        $this->free      += $this->cur_result['getfree'];
        $this->all_free  += $this->cur_result['getfree'];

        $user_win = array_sum($this->cur_result['score']);
        $this->all_win += $user_win - $use;
        $this->useGold($user_win - $use);

        Common::SyncPlatformPlayGame($this->uid, $use, $user_win, $this->roomRule['app_rid'] ?? '');

        $latest = DBInstance::GetTableWords('user_register', 'gold', ['uid' => $this->uid]);
        if ($latest && isset($latest['gold'])) {
            $this->userInfo['gold'] = $latest['gold'];
        }

        // 大奖评级
        $reward = 0;
        foreach (BIG_WIN as $key => $value) {
            if (intval($user_win / $this->use) >= $value) {
                $reward = $key;
                break;
            }
        }

        $this->all_score += $user_win;

        // -------- 10. 下发 --------
        $data = [
            'disappear'  => $this->cur_result['disappear'],
            'score'      => $this->cur_result['score'],
            'logo_info'  => $this->cur_result['logo_info'],
            'cur_gold'   => $this->cur_result['cur_gold'],
            'cur_time'   => $this->cur_result['cur_time'],
            'double_arr' => $this->cur_result['double_arr'],
            'free_logo'  => $this->cur_result['free_logo'],
            'curgrade'   => $this->betGold,
            'curdouble'  => $this->betDouble,
            'conscore'   => $use,
            'map'        => $this->map,
            'free'       => $this->free,
            'getfree'    => $this->cur_result['getfree'],
            'reward'     => $reward,
            'user_gold'  => $this->userInfo['gold'],
            'all_score'  => $this->all_score,
        ];

        $record_data = [
            'score'      => $this->cur_result['score'],
            'cur_gold'   => $this->cur_result['cur_gold'],
            'cur_time'   => $this->cur_result['cur_time'],
            'free_logo'  => $this->cur_result['free_logo'],
            'curgrade'   => $this->betGold,
            'curdouble'  => $this->betDouble,
            'conscore'   => $use,
            'free'       => $this->free,
            'getfree'    => $this->cur_result['getfree'],
            'reward'     => $reward,
            'all_score'  => $this->all_score,
        ];
        $this->save_maps[] = $record_data;

        // -------- 11. 免费保底计数 --------
        $this->updateGuaranteeState($use);

        Logic::SendRight($this->uid, 'Msg_MJHLT_Start', $data);

        // -------- 12. 后台统计 --------
        DBInstance::IncrementUserGet($this->uid, $user_win - $use);

        if (abs($control) != 2) {
            Logic::InsertProfit(Logic::$betLevel[$level_index], $user_win - $use);
        }

        if ($use) {
            $this->distime = count($this->map) - 1;
            $this->free_get = 0;
            $this->freedistime = 0;
        } else {
            $this->free_get += $user_win;
            $this->freedistime += count($this->map) - 1;
        }

        if ($this->free <= 0) {
            DBInstance::InsertGameRecord(
                $this->roomRule['gtype'],
                $this->roomRule['level'],
                $this->uid,
                $this->use,
                ($this->all_score - $this->use),
                $this->distime,
                $this->all_free,
                $this->save_maps,
                $this->freedistime
            );
        }

        $double = intval($user_win / $this->use);
        if ($user_win > HORSE['score'] && $double >= HORSE['double']) {
            Logic::HorseLamp($this->uid, $user_win, $double);
        }
    }

    // ================================================================
    // 子方法：Msg_MJHLT_Start 的拆解
    // ================================================================

    /**
     * 下注/免费状态准备
     */
    private function prepareBetState($new_bet_gold, $new_bet_double, $use)
    {
        if ($this->free > 0) {
            // 免费中: 不改动任何下注状态, 沿用进入免费时的档位
            return;
        }

        $this->all_score = 0;
        $this->all_free  = 0;
        $this->save_maps = [];

        // 注档变化时重置免费保底进度 (防止低注刷保底再跳高注)
        if (
            ($this->guarantee_bet_gold > 0 || $this->guarantee_bet_double > 0)
            && ($this->guarantee_bet_gold != $new_bet_gold || $this->guarantee_bet_double != $new_bet_double)
        ) {
            $this->normal_round_count = 0;
            $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
            $this->is_free_guarantee = false;
        }

        $this->guarantee_bet_gold = $new_bet_gold;
        $this->guarantee_bet_double = $new_bet_double;
        $this->betGold   = $new_bet_gold;
        $this->betDouble = $new_bet_double;
        $this->use = $new_bet_gold * $new_bet_double * GAME_DOUBLE;
    }

    /**
     * 根据控制表构造 mapPossible / wildPossible
     */
    private function buildMapPossible($control, $control_map)
    {
        $this->mapPossible  = [];
        $this->wildPossible = [];

        if ($this->free > 0 && !empty($control_map[$control]['free_map']) && is_array($control_map[$control]['free_map'])) {
            $this->mapPossible = $control_map[$control]['free_map'];
            for ($i = 0; $i < 5; $i++) {
                $this->wildPossible[$i] = ($i && isset($control_map[$control]['free_wild'])) ? $control_map[$control]['free_wild'][$i] : 0;
            }
        } elseif (empty($control_map[$control]) || !is_array($control_map[$control]['map'])) {
            for ($i = 0; $i < 5; $i++) {
                $this->mapPossible[$i]  = POSSIBLE;
                $this->wildPossible[$i] = mt_rand(1, 6) ? 20 : 0;
            }
        } else {
            $this->mapPossible = $control_map[$control]['map'];
            for ($i = 0; $i < 5; $i++) {
                $this->wildPossible[$i] = ($i && isset($control_map[$control]['wild'])) ? $control_map[$control]['wild'][$i] : 0;
            }
        }
    }

    /**
     * 免费轮参数构造
     */
    private function buildFreeRoundParams($is_free_round)
    {
        $params = [
            'max_score'        => PHP_INT_MAX,
            'total_max_score'  => PHP_INT_MAX,
            'total_left_score' => PHP_INT_MAX,
            'reroll_min_score' => 0,
            'total_min_score'  => 0,
            'total_need_score' => 0,
            'need_boost'       => false,
            'boost_min_score'  => 0,
            'boost_max_score'  => PHP_INT_MAX,
            'is_boom_round'    => false,
        ];

        if (!$is_free_round) {
            return $params;
        }

        // 进入免费时的档位设置
        if ($this->free_prize_level == FREE_LEVEL_NORMAL) {
            $max_double       = 15;
            $reroll_min_double = 2;
        } elseif ($this->free_prize_level == FREE_LEVEL_BIG) {
            $max_double       = 130;
            $reroll_min_double = 20;
        } else {
            $max_double       = 300;
            $reroll_min_double = 80;
        }

        $params['max_score']       = $this->use * $max_double;
        $params['total_max_score'] = $this->use * $this->free_total_limit_double;
        $params['total_left_score']= max(0, $params['total_max_score'] - $this->free_get);
        $params['reroll_min_score']= $this->use * $reroll_min_double;
        $params['total_min_score'] = $this->use * $this->free_total_min_double;
        $params['total_need_score']= max(0, $params['total_min_score'] - $this->free_get);

        // 当前这转是不是指定的爆奖转?
        if (!$this->free_boom_used && $this->free_boom_left_count > 0 && $this->free == $this->free_boom_left_count) {
            $params['is_boom_round']   = true;
            $params['need_boost']      = true;
            $params['boost_min_score'] = $this->use *<?php

date_default_timezone_set('Asia/Shanghai');

use Workerman\Lib\Timer;

// ==================== 常量定义 ====================

define('ERTONG', 1);
define('ERTIAO', 2);
define('WUTONG', 3);
define('WUTIAO', 4);
define('BAWAN', 5);
define('BAIBAN', 6);
define('HONGZHONG', 7);
define('FACAI', 8);
define('SANTONG', 9);
define('FREE', 10);
define('BAIDA', 11);
define('GAME_DOUBLE', 20);

// 控制逻辑中引用的外部常量
defined('MAX_WIN_SCORE') || define('MAX_WIN_SCORE', 1000000);

// 不同图案连击的赔付倍率表 (3连/4连/5连)
define('DOUBLE', [
    ERTONG    => [3 => 1,  4 => 3,   5 => 6],
    ERTIAO    => [3 => 1,  4 => 3,   5 => 6],
    SANTONG   => [3 => 2,  4 => 4,   5 => 10],
    WUTONG    => [3 => 3,  4 => 5,   5 => 12],
    WUTIAO    => [3 => 3,  4 => 5,   5 => 12],
    BAWAN     => [3 => 5,  4 => 10,  5 => 15],
    BAIBAN    => [3 => 6,  4 => 15,  5 => 30],
    HONGZHONG => [3 => 8,  4 => 20,  5 => 40],
    FACAI     => [3 => 10, 4 => 25,  5 => 50],
]);

// 图案出现概率 (普通地图 / 免费地图)
define('POSSIBLE',      [ERTONG => 50, ERTIAO => 50, SANTONG => 50, WUTONG => 30, WUTIAO => 30, BAWAN => 15, BAIBAN => 7,  HONGZHONG => 3, FACAI => 1, FREE => 200]);
define('FREEPOSSIBLE',  [ERTONG => 50, ERTIAO => 50, SANTONG => 50, WUTONG => 30, WUTIAO => 30, BAWAN => 10, BAIBAN => 3,  HONGZHONG => 2, FACAI => 1, FREE => 8]);

// 大奖评级 (3=大/2=中/1=小)
define('BIG_WIN', [3 => 40, 2 => 20, 1 => 10]);

// Wild 柱阈值 (万分之 N)
define('WILD_PERCENT', 5000);

// 跑马灯触发条件
define('HORSE', ['double' => 20, 'score' => 1]);

// 免费游戏档位
define('FREE_LEVEL_NORMAL', 0);   // 普通
define('FREE_LEVEL_BIG',    1);   // 大奖/超级
define('FREE_LEVEL_JACKPOT',2);   // 爆奖


/**
 * 麻将/老虎机游戏主逻辑
 */
class Table
{
    // ==================== 玩家状态 ====================
    private $userInfo = [];
    private $uid = 0;
    private $free = 0;             // 剩余免费次数
    private $map = [];             // 地图 (各轮)
    private $betGold = 0;          // 当前下注档位
    private $betDouble = 1;        // 当前下注倍率
    private $roomRule = [];        // 房间配置
    private $use = 0;              // 实际消耗金币
    private $mTimer = 0;
    private $mapPossible = [];     // 当前地图概率表 (5列)
    private $wildPossible = [];    // Wild 出现概率 (5列)

    // ==================== 单局结算 ====================
    private $cur_result = [];
    private $deal_map = [];
    private $all_score = 0;        // 整局总得分
    private $all_free = 0;         // 整局获得的免费次数
    private $free_get = 0;         // 免费轮累计得分
    private $save_maps = [];
    private $distime = 0;
    private $freedistime = 0;
    private $next_free_count = 999;

    // ==================== 免费保底 ====================
    private $normal_round_count = 0;
    private $free_guarantee_threshold = 0;
    private $is_free_guarantee = false;
    private $free_guarantee_min = 150;
    private $free_guarantee_max = 250;

    // ==================== 免费游戏档位 ====================
    private $free_total_limit_double = 30;
    private $free_total_min_double = 0;
    private $free_prize_level = 0;
    private $force_free_trigger = false;

    private $free_boom_left_count = 0;   // 爆奖在剩余第几转出现
    private $free_boom_min_double = 0;
    private $free_boom_max_double = 0;
    private $free_boom_used = false;

    private $guarantee_bet_gold = 0;
    private $guarantee_bet_double = 0;
    private $guarantee_count = 0;

    // ==================== 胜负统计 ====================
    private $all_win = 0;


    // ================================================================
    // 构造与入口
    // ================================================================

    public function __construct($msg)
    {
        $this->roomRule = $msg;
        $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
        $this->resetCurResult();
    }

    public function All_RECV($message)
    {
        switch ($message['event']) {
            case 'Msg_MJHLT_Start':
                $this->Msg_MJHLT_Start($message);
                break;
            case 'Msg_Game_Out':
                $this->Msg_Game_Out($message);
                break;
            case 'Msg_Game_RoomInfo':
                $this->Msg_Game_RoomInfo($message);
                break;
            default:
                Logic::SendError($message['uid'], $message['event'], '');
                MyTools::msg('uid:' . $message['uid'] . '-----UnKnown!!!!!!!--------' . $message['event'], true);
                break;
        }
    }

    // ================================================================
    // 房间信息 / 进房 / 离线
    // ================================================================

    private function Msg_Game_RoomInfo($message)
    {
        if ($this->uid && $this->uid == $message['uid']) {
            Logic::SendRight($this->uid, 'Msg_Game_RoomInfo', [
                'free'         => $this->free,
                'all_score'    => $this->all_score,
                'all_free'     => $this->all_free,
                'curgrade'     => $this->betGold,
                'curdouble'    => $this->betDouble,
                'map'          => $this->map,
                'max_multiple' => max($this->roomRule['score_arr']),
                'level'        => $this->roomRule['level'],
                'score_arr'    => $this->roomRule['score_arr'],
                'double_arr'   => $this->roomRule['double_arr'],
                'base_arr'     => [GAME_DOUBLE],
                'min_gold'     => $this->roomRule['min_gold'],
                'max_gold'     => $this->roomRule['max_gold'],
                'bet_min'      => $this->roomRule['bet_min'] ?? 10000,
                'bet_max'      => $this->roomRule['bet_max'] ?? 200000,
                'gold'         => $this->userInfo['gold'],
            ]);
        } else {
            Logic::SendError($message['uid'], 'Msg_Game_RoomInfo', '无效操作');
        }
    }

    public function UserOnline($client_id, $uid)
    {
        Timer::del($this->mTimer);
        $this->Msg_Game_RoomInfo(['uid' => $uid]);
    }

    public function UserOff($uid)
    {
        $this->saveGameCache();
        $this->mTimer = Timer::add(60, function () {
            $this->Msg_Game_Out(['uid' => $this->uid]);
        }, [], false);
    }

    public function EnterRoom($msg)
    {
        $this->uid = $msg['uid'];
        $ret = DBInstance::GetGameCache($this->uid, $this->roomRule['gtype'], $this->roomRule['level']);

        if (!$ret) {
            $this->betGold   = min($this->roomRule['score_arr']);
            $this->betDouble = min($this->roomRule['double_arr']);
            DBInstance::InsertGameCache([
                'uid'        => $this->uid,
                'gtype'      => $this->roomRule['gtype'],
                'level'      => $this->roomRule['level'],
                'map'        => '[]',
                'bet_gold'   => $this->betGold,
                'bet_double' => $this->betDouble,
                'free'       => 0,
            ]);
            $this->guarantee_count = 0;
        } else {
            $this->map  = $ret['map'];
            $this->free = $ret['free'];

            if ($this->free > 0) {
                $this->betGold   = $ret['bet_gold'];
                $this->betDouble = $ret['bet_double'];
            } else {
                $this->betGold   = min($this->roomRule['score_arr']);
                $this->betDouble = min($this->roomRule['double_arr']);
            }

            $this->guarantee_count = $ret['vals']['guarantee_count'] ?? 0;
            $this->all_score       = $ret['vals']['all_score']       ?? 0;
            $this->all_free        = $ret['vals']['all_free']        ?? 0;
            $this->use             = $this->betGold * $this->betDouble * GAME_DOUBLE;

            if ($this->free) {
                $this->distime     = $ret['vals']['distime'];
                $this->free_get    = $ret['vals']['free_get'];
                $this->save_maps   = $ret['vals']['save_maps'];
                $this->freedistime = $ret['vals']['freedistime'];
            }
        }

        $this->map      = [];
        $this->deal_map = [];
        $this->resetCurResult();

        if ($this->free <= 0) {
            $this->free = 0;
            $this->normal_round_count = 0;
            $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
            $this->free_prize_level = 0;
            $this->free_total_limit_double = 30;
            $this->free_total_min_double = 0;
            $this->free_boom_left_count = 0;
            $this->free_boom_min_double = 0;
            $this->free_boom_max_double = 0;
            $this->free_boom_used = false;
        }

        $this->userInfo = $msg;
        $this->Msg_Game_RoomInfo(['uid' => $this->uid]);
    }

    public function DisRoom($msg = [])
    {
        $this->Msg_Game_Out(['uid' => $this->uid]);
    }

    // ================================================================
    // 退出/转账 (与主逻辑无关的基础设施)
    // ================================================================

    private function Msg_Game_Out($message)
    {
        Timer::del($this->mTimer);

        $gold = DBInstance::GetTableOneWord('user_register', 'gold', ['uid' => $this->uid]);
        $bank = DBInstance::GetTableOneWord('user_register', 'bank', ['uid' => $this->uid]);
        Logic::SendRight($this->uid, 'Msg_Game_Out', ['gold' => $gold, 'bank' => $bank]);

        $this->saveGameCache();

        $olddata = [
            'rid'     => $this->roomRule['rid'],
            'win'     => [],
            'palyers' => [$this->uid => $this->userInfo],
            'result'  => ['uid' => []],
            'gtype'   => $this->roomRule['gtype'],
        ];
        Logic::RoomOld($olddata);
    }

    public function ChangeGold($msg)
    {
        $uid = $msg['uid'];
        $before = DBInstance::GetUser(['uid' => $uid]);
        DBInstance::IncrementGolds('bank', $uid, $msg['data']['num']);
        DBInstance::InsertUserProfit($uid, $msg['data']['from'], $msg['data']['type'], $msg['data']['num'], $before);
        $data = DBInstance::GetTableWords('user_register', 'bank,gold', ['uid' => $uid]);
        $this->userInfo['bank'] = $data['bank'];
        Logic::SendRight($this->uid, 'Msg_Hall_ChangeGolds', $data);
    }

    public function BackTransfer($message)
    {
        $ret = DBInstance::BackTransfer($message['data']['out_id']);
        $uid = $message['uid'];
        $data = $message['data'];
        $user = DBInstance::GetTableWords('user_register', 'bank,gold', ['uid' => $uid]);

        $message['data'] = [
            'bank'   => $user['bank'],
            'gold'   => $user['gold'],
            'status' => $ret ? 0 : 2,
        ];
        Common::SendToClient($message, $data['client_id']);

        if ($ret) {
            $data = ['bank' => $user['bank'], 'gold' => $user['gold']];
            $this->userInfo['bank'] = $data['bank'];
            Logic::SendRight($this->uid, 'Msg_Hall_ChangeGolds', $data);
        }
    }

    // ================================================================
    // 主流程: 一局游戏开始
    // ================================================================

    private function Msg_MJHLT_Start($message)
    {
        // -------- 1. 参数与校验 --------
        $betLevelIndex = $message['data']['score'] * $message['data']['double'];
        if ($betLevelIndex <= 0) {
            Logic::SendError($message['uid'], $message['event'], '等级错误');
            return;
        }
        if (empty(Logic::$betLevel[$betLevelIndex])) {
            $levelValues = array_values(Logic::$betLevel);
            Logic::$betLevel[$betLevelIndex] = !empty($levelValues) ? min($levelValues) : 1;
        }

        $use = ($this->free <= 0) ? ($message['data']['score'] * $message['data']['double'] * GAME_DOUBLE) : 0;

        if ($message['uid'] != $this->uid || $this->userInfo['gold'] < $use) {
            Logic::SendError($message['uid'], $message['event'], '无效操作');
            return;
        }

        $betMin = $this->roomRule['bet_min'] ?? 10000;
        $betMax = $this->roomRule['bet_max'] ?? 200000;
        if ($this->free <= 0 && ($use < $betMin || $use > $betMax)) {
            Logic::SendError($message['uid'], $message['event'], '投注金额超出范围');
            return;
        }

        // -------- 2. 免费档位与下注状态初始化 --------
        $this->prepareBetState($message['data']['score'], $message['data']['double'], $use);

        // -------- 3. 控制表读取 --------
        $logo_num = DBInstance::GetControlMap($this->uid, $this->roomRule['gtype'], $this->roomRule['level']);
        $level_index = $this->betGold * $this->betDouble;
        $control = $logo_num ? -2 : DBInstance::GetLBControl($this->uid, $this->roomRule['gtype'], Logic::$betLevel[$level_index]);
        $control_map = DBInstance::GetControlInfo('control_mjhlt', ['level' => $control]);

        $this->buildMapPossible($control, $control_map);

        // -------- 4. 免费下一转倒计时 --------
        if ($control >= 0) {
            $this->next_free_count--;
        }
        if (
            (isset($control_map[$control]['free_cirle']) && $this->next_free_count > $control_map[$control]['free_cirle'])
            || $use <= 0
            || $control < 0
        ) {
            $this->next_free_count = max($control_map[$control]['free_cirle'] ?? 0, 50);
        }

        // -------- 5. 免费轮参数 --------
        $is_free_round = ($this->free > 0 && $this->use > 0);
        $freeParams = $this->buildFreeRoundParams($is_free_round);

        // -------- 6. 生成地图 (最多 loop_max 次重摇) --------
        $loop_max = $this->calcLoopMax($is_free_round, $freeParams);
        $best = $this->rollMapLoop($loop_max, $is_free_round, $freeParams, $logo_num, $control);

        // 若爆奖模式未找到合格地图, 使用最佳结果兜底
        if ($is_free_round && $freeParams['need_boost'] && !$best['valid_found'] && $best['best_result'] !== null) {
            $this->map       = $best['best_map'];
            $this->deal_map  = $best['best_deal_map'];
            $this->cur_result= $best['best_result'];
            if ($freeParams['is_boom_round']) {
                $this->free_boom_used = true;
            }
        }

        // -------- 7. 兜底: 若最终结果仍超出限制, 清空本轮 --------
        $this->finalizeCurResult($is_free_round, $freeParams);

        // -------- 8. 结算新免费局 (进入新免费游戏时设置档位) --------
        if ($this->cur_result['getfree'] > 0 && $this->free <= 0) {
            $this->initFreePrizeLevel();
        }

        // -------- 9. 扣金币 / 发奖 / 写库 --------
        if ($this->free > 0) {
            $this->free--;
        }
        $this->free      += $this->cur_result['getfree'];
        $this->all_free  += $this->cur_result['getfree'];

        $user_win = array_sum($this->cur_result['score']);
        $this->all_win += $user_win - $use;
        $this->useGold($user_win - $use);

        Common::SyncPlatformPlayGame($this->uid, $use, $user_win, $this->roomRule['app_rid'] ?? '');

        $latest = DBInstance::GetTableWords('user_register', 'gold', ['uid' => $this->uid]);
        if ($latest && isset($latest['gold'])) {
            $this->userInfo['gold'] = $latest['gold'];
        }

        // 大奖评级
        $reward = 0;
        foreach (BIG_WIN as $key => $value) {
            if (intval($user_win / $this->use) >= $value) {
                $reward = $key;
                break;
            }
        }

        $this->all_score += $user_win;

        // -------- 10. 下发 --------
        $data = [
            'disappear'  => $this->cur_result['disappear'],
            'score'      => $this->cur_result['score'],
            'logo_info'  => $this->cur_result['logo_info'],
            'cur_gold'   => $this->cur_result['cur_gold'],
            'cur_time'   => $this->cur_result['cur_time'],
            'double_arr' => $this->cur_result['double_arr'],
            'free_logo'  => $this->cur_result['free_logo'],
            'curgrade'   => $this->betGold,
            'curdouble'  => $this->betDouble,
            'conscore'   => $use,
            'map'        => $this->map,
            'free'       => $this->free,
            'getfree'    => $this->cur_result['getfree'],
            'reward'     => $reward,
            'user_gold'  => $this->userInfo['gold'],
            'all_score'  => $this->all_score,
        ];

        $record_data = [
            'score'      => $this->cur_result['score'],
            'cur_gold'   => $this->cur_result['cur_gold'],
            'cur_time'   => $this->cur_result['cur_time'],
            'free_logo'  => $this->cur_result['free_logo'],
            'curgrade'   => $this->betGold,
            'curdouble'  => $this->betDouble,
            'conscore'   => $use,
            'free'       => $this->free,
            'getfree'    => $this->cur_result['getfree'],
            'reward'     => $reward,
            'all_score'  => $this->all_score,
        ];
        $this->save_maps[] = $record_data;

        // -------- 11. 免费保底计数 --------
        $this->updateGuaranteeState($use);

        Logic::SendRight($this->uid, 'Msg_MJHLT_Start', $data);

        // -------- 12. 后台统计 --------
        DBInstance::IncrementUserGet($this->uid, $user_win - $use);

        if (abs($control) != 2) {
            Logic::InsertProfit(Logic::$betLevel[$level_index], $user_win - $use);
        }

        if ($use) {
            $this->distime = count($this->map) - 1;
            $this->free_get = 0;
            $this->freedistime = 0;
        } else {
            $this->free_get += $user_win;
            $this->freedistime += count($this->map) - 1;
        }

        if ($this->free <= 0) {
            DBInstance::InsertGameRecord(
                $this->roomRule['gtype'],
                $this->roomRule['level'],
                $this->uid,
                $this->use,
                ($this->all_score - $this->use),
                $this->distime,
                $this->all_free,
                $this->save_maps,
                $this->freedistime
            );
        }

        $double = intval($user_win / $this->use);
        if ($user_win > HORSE['score'] && $double >= HORSE['double']) {
            Logic::HorseLamp($this->uid, $user_win, $double);
        }
    }

    // ================================================================
    // 子方法：Msg_MJHLT_Start 的拆解
    // ================================================================

    /**
     * 下注/免费状态准备
     */
    private function prepareBetState($new_bet_gold, $new_bet_double, $use)
    {
        if ($this->free > 0) {
            // 免费中: 不改动任何下注状态, 沿用进入免费时的档位
            return;
        }

        $this->all_score = 0;
        $this->all_free  = 0;
        $this->save_maps = [];

        // 注档变化时重置免费保底进度 (防止低注刷保底再跳高注)
        if (
            ($this->guarantee_bet_gold > 0 || $this->guarantee_bet_double > 0)
            && ($this->guarantee_bet_gold != $new_bet_gold || $this->guarantee_bet_double != $new_bet_double)
        ) {
            $this->normal_round_count = 0;
            $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
            $this->is_free_guarantee = false;
        }

        $this->guarantee_bet_gold = $new_bet_gold;
        $this->guarantee_bet_double = $new_bet_double;
        $this->betGold   = $new_bet_gold;
        $this->betDouble = $new_bet_double;
        $this->use = $new_bet_gold * $new_bet_double * GAME_DOUBLE;
    }

    /**
     * 根据控制表构造 mapPossible / wildPossible
     */
    private function buildMapPossible($control, $control_map)
    {
        $this->mapPossible  = [];
        $this->wildPossible = [];

        if ($this->free > 0 && !empty($control_map[$control]['free_map']) && is_array($control_map[$control]['free_map'])) {
            $this->mapPossible = $control_map[$control]['free_map'];
            for ($i = 0; $i < 5; $i++) {
                $this->wildPossible[$i] = ($i && isset($control_map[$control]['free_wild'])) ? $control_map[$control]['free_wild'][$i] : 0;
            }
        } elseif (empty($control_map[$control]) || !is_array($control_map[$control]['map'])) {
            for ($i = 0; $i < 5; $i++) {
                $this->mapPossible[$i]  = POSSIBLE;
                $this->wildPossible[$i] = mt_rand(1, 6) ? 20 : 0;
            }
        } else {
            $this->mapPossible = $control_map[$control]['map'];
            for ($i = 0; $i < 5; $i++) {
                $this->wildPossible[$i] = ($i && isset($control_map[$control]['wild'])) ? $control_map[$control]['wild'][$i] : 0;
            }
        }
    }

    /**
     * 免费轮参数构造
     */
    private function buildFreeRoundParams($is_free_round)
    {
        $params = [
            'max_score'        => PHP_INT_MAX,
            'total_max_score'  => PHP_INT_MAX,
            'total_left_score' => PHP_INT_MAX,
            'reroll_min_score' => 0,
            'total_min_score'  => 0,
            'total_need_score' => 0,
            'need_boost'       => false,
            'boost_min_score'  => 0,
            'boost_max_score'  => PHP_INT_MAX,
            'is_boom_round'    => false,
        ];

        if (!$is_free_round) {
            return $params;
        }

        // 进入免费时的档位设置
        if ($this->free_prize_level == FREE_LEVEL_NORMAL) {
            $max_double       = 15;
            $reroll_min_double = 2;
        } elseif ($this->free_prize_level == FREE_LEVEL_BIG) {
            $max_double       = 130;
            $reroll_min_double = 20;
        } else {
            $max_double       = 300;
            $reroll_min_double = 80;
        }

        $params['max_score']       = $this->use * $max_double;
        $params['total_max_score'] = $this->use * $this->free_total_limit_double;
        $params['total_left_score']= max(0, $params['total_max_score'] - $this->free_get);
        $params['reroll_min_score']= $this->use * $reroll_min_double;
        $params['total_min_score'] = $this->use * $this->free_total_min_double;
        $params['total_need_score']= max(0, $params['total_min_score'] - $this->free_get);

        // 当前这转是不是指定的爆奖转?
        if (!$this->free_boom_used && $this->free_boom_left_count > 0 && $this->free == $this->free_boom_left_count) {
            $params['is_boom_round']   = true;
            $params['need_boost']      = true;
            $params['boost_min_score'] = $this->use * $this->free_boom_min_double;
            $params['boost_max_score'] = $<?php

date_default_timezone_set('Asia/Shanghai');

use Workerman\Lib\Timer;

// ==================== 常量定义 ====================

define('ERTONG', 1);
define('ERTIAO', 2);
define('WUTONG', 3);
define('WUTIAO', 4);
define('BAWAN', 5);
define('BAIBAN', 6);
define('HONGZHONG', 7);
define('FACAI', 8);
define('SANTONG', 9);
define('FREE', 10);
define('BAIDA', 11);
define('GAME_DOUBLE', 20);

// 控制逻辑中引用的外部常量
defined('MAX_WIN_SCORE') || define('MAX_WIN_SCORE', 1000000);

// 不同图案连击的赔付倍率表 (3连/4连/5连)
define('DOUBLE', [
    ERTONG    => [3 => 1,  4 => 3,   5 => 6],
    ERTIAO    => [3 => 1,  4 => 3,   5 => 6],
    SANTONG   => [3 => 2,  4 => 4,   5 => 10],
    WUTONG    => [3 => 3,  4 => 5,   5 => 12],
    WUTIAO    => [3 => 3,  4 => 5,   5 => 12],
    BAWAN     => [3 => 5,  4 => 10,  5 => 15],
    BAIBAN    => [3 => 6,  4 => 15,  5 => 30],
    HONGZHONG => [3 => 8,  4 => 20,  5 => 40],
    FACAI     => [3 => 10, 4 => 25,  5 => 50],
]);

// 图案出现概率 (普通地图 / 免费地图)
define('POSSIBLE',      [ERTONG => 50, ERTIAO => 50, SANTONG => 50, WUTONG => 30, WUTIAO => 30, BAWAN => 15, BAIBAN => 7,  HONGZHONG => 3, FACAI => 1, FREE => 200]);
define('FREEPOSSIBLE',  [ERTONG => 50, ERTIAO => 50, SANTONG => 50, WUTONG => 30, WUTIAO => 30, BAWAN => 10, BAIBAN => 3,  HONGZHONG => 2, FACAI => 1, FREE => 8]);

// 大奖评级 (3=大/2=中/1=小)
define('BIG_WIN', [3 => 40, 2 => 20, 1 => 10]);

// Wild 柱阈值 (万分之 N)
define('WILD_PERCENT', 5000);

// 跑马灯触发条件
define('HORSE', ['double' => 20, 'score' => 1]);

// 免费游戏档位
define('FREE_LEVEL_NORMAL', 0);   // 普通
define('FREE_LEVEL_BIG',    1);   // 大奖/超级
define('FREE_LEVEL_JACKPOT',2);   // 爆奖


/**
 * 麻将/老虎机游戏主逻辑
 */
class Table
{
    // ==================== 玩家状态 ====================
    private $userInfo = [];
    private $uid = 0;
    private $free = 0;             // 剩余免费次数
    private $map = [];             // 地图 (各轮)
    private $betGold = 0;          // 当前下注档位
    private $betDouble = 1;        // 当前下注倍率
    private $roomRule = [];        // 房间配置
    private $use = 0;              // 实际消耗金币
    private $mTimer = 0;
    private $mapPossible = [];     // 当前地图概率表 (5列)
    private $wildPossible = [];    // Wild 出现概率 (5列)

    // ==================== 单局结算 ====================
    private $cur_result = [];
    private $deal_map = [];
    private $all_score = 0;        // 整局总得分
    private $all_free = 0;         // 整局获得的免费次数
    private $free_get = 0;         // 免费轮累计得分
    private $save_maps = [];
    private $distime = 0;
    private $freedistime = 0;
    private $next_free_count = 999;

    // ==================== 免费保底 ====================
    private $normal_round_count = 0;
    private $free_guarantee_threshold = 0;
    private $is_free_guarantee = false;
    private $free_guarantee_min = 150;
    private $free_guarantee_max = 250;

    // ==================== 免费游戏档位 ====================
    private $free_total_limit_double = 30;
    private $free_total_min_double = 0;
    private $free_prize_level = 0;
    private $force_free_trigger = false;

    private $free_boom_left_count = 0;   // 爆奖在剩余第几转出现
    private $free_boom_min_double = 0;
    private $free_boom_max_double = 0;
    private $free_boom_used = false;

    private $guarantee_bet_gold = 0;
    private $guarantee_bet_double = 0;
    private $guarantee_count = 0;

    // ==================== 胜负统计 ====================
    private $all_win = 0;


    // ================================================================
    // 构造与入口
    // ================================================================

    public function __construct($msg)
    {
        $this->roomRule = $msg;
        $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
        $this->resetCurResult();
    }

    public function All_RECV($message)
    {
        switch ($message['event']) {
            case 'Msg_MJHLT_Start':
                $this->Msg_MJHLT_Start($message);
                break;
            case 'Msg_Game_Out':
                $this->Msg_Game_Out($message);
                break;
            case 'Msg_Game_RoomInfo':
                $this->Msg_Game_RoomInfo($message);
                break;
            default:
                Logic::SendError($message['uid'], $message['event'], '');
                MyTools::msg('uid:' . $message['uid'] . '-----UnKnown!!!!!!!--------' . $message['event'], true);
                break;
        }
    }

    // ================================================================
    // 房间信息 / 进房 / 离线
    // ================================================================

    private function Msg_Game_RoomInfo($message)
    {
        if ($this->uid && $this->uid == $message['uid']) {
            Logic::SendRight($this->uid, 'Msg_Game_RoomInfo', [
                'free'         => $this->free,
                'all_score'    => $this->all_score,
                'all_free'     => $this->all_free,
                'curgrade'     => $this->betGold,
                'curdouble'    => $this->betDouble,
                'map'          => $this->map,
                'max_multiple' => max($this->roomRule['score_arr']),
                'level'        => $this->roomRule['level'],
                'score_arr'    => $this->roomRule['score_arr'],
                'double_arr'   => $this->roomRule['double_arr'],
                'base_arr'     => [GAME_DOUBLE],
                'min_gold'     => $this->roomRule['min_gold'],
                'max_gold'     => $this->roomRule['max_gold'],
                'bet_min'      => $this->roomRule['bet_min'] ?? 10000,
                'bet_max'      => $this->roomRule['bet_max'] ?? 200000,
                'gold'         => $this->userInfo['gold'],
            ]);
        } else {
            Logic::SendError($message['uid'], 'Msg_Game_RoomInfo', '无效操作');
        }
    }

    public function UserOnline($client_id, $uid)
    {
        Timer::del($this->mTimer);
        $this->Msg_Game_RoomInfo(['uid' => $uid]);
    }

    public function UserOff($uid)
    {
        $this->saveGameCache();
        $this->mTimer = Timer::add(60, function () {
            $this->Msg_Game_Out(['uid' => $this->uid]);
        }, [], false);
    }

    public function EnterRoom($msg)
    {
        $this->uid = $msg['uid'];
        $ret = DBInstance::GetGameCache($this->uid, $this->roomRule['gtype'], $this->roomRule['level']);

        if (!$ret) {
            $this->betGold   = min($this->roomRule['score_arr']);
            $this->betDouble = min($this->roomRule['double_arr']);
            DBInstance::InsertGameCache([
                'uid'        => $this->uid,
                'gtype'      => $this->roomRule['gtype'],
                'level'      => $this->roomRule['level'],
                'map'        => '[]',
                'bet_gold'   => $this->betGold,
                'bet_double' => $this->betDouble,
                'free'       => 0,
            ]);
            $this->guarantee_count = 0;
        } else {
            $this->map  = $ret['map'];
            $this->free = $ret['free'];

            if ($this->free > 0) {
                $this->betGold   = $ret['bet_gold'];
                $this->betDouble = $ret['bet_double'];
            } else {
                $this->betGold   = min($this->roomRule['score_arr']);
                $this->betDouble = min($this->roomRule['double_arr']);
            }

            $this->guarantee_count = $ret['vals']['guarantee_count'] ?? 0;
            $this->all_score       = $ret['vals']['all_score']       ?? 0;
            $this->all_free        = $ret['vals']['all_free']        ?? 0;
            $this->use             = $this->betGold * $this->betDouble * GAME_DOUBLE;

            if ($this->free) {
                $this->distime     = $ret['vals']['distime'];
                $this->free_get    = $ret['vals']['free_get'];
                $this->save_maps   = $ret['vals']['save_maps'];
                $this->freedistime = $ret['vals']['freedistime'];
            }
        }

        $this->map      = [];
        $this->deal_map = [];
        $this->resetCurResult();

        if ($this->free <= 0) {
            $this->free = 0;
            $this->normal_round_count = 0;
            $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
            $this->free_prize_level = 0;
            $this->free_total_limit_double = 30;
            $this->free_total_min_double = 0;
            $this->free_boom_left_count = 0;
            $this->free_boom_min_double = 0;
            $this->free_boom_max_double = 0;
            $this->free_boom_used = false;
        }

        $this->userInfo = $msg;
        $this->Msg_Game_RoomInfo(['uid' => $this->uid]);
    }

    public function DisRoom($msg = [])
    {
        $this->Msg_Game_Out(['uid' => $this->uid]);
    }

    // ================================================================
    // 退出/转账 (与主逻辑无关的基础设施)
    // ================================================================

    private function Msg_Game_Out($message)
    {
        Timer::del($this->mTimer);

        $gold = DBInstance::GetTableOneWord('user_register', 'gold', ['uid' => $this->uid]);
        $bank = DBInstance::GetTableOneWord('user_register', 'bank', ['uid' => $this->uid]);
        Logic::SendRight($this->uid, 'Msg_Game_Out', ['gold' => $gold, 'bank' => $bank]);

        $this->saveGameCache();

        $olddata = [
            'rid'     => $this->roomRule['rid'],
            'win'     => [],
            'palyers' => [$this->uid => $this->userInfo],
            'result'  => ['uid' => []],
            'gtype'   => $this->roomRule['gtype'],
        ];
        Logic::RoomOld($olddata);
    }

    public function ChangeGold($msg)
    {
        $uid = $msg['uid'];
        $before = DBInstance::GetUser(['uid' => $uid]);
        DBInstance::IncrementGolds('bank', $uid, $msg['data']['num']);
        DBInstance::InsertUserProfit($uid, $msg['data']['from'], $msg['data']['type'], $msg['data']['num'], $before);
        $data = DBInstance::GetTableWords('user_register', 'bank,gold', ['uid' => $uid]);
        $this->userInfo['bank'] = $data['bank'];
        Logic::SendRight($this->uid, 'Msg_Hall_ChangeGolds', $data);
    }

    public function BackTransfer($message)
    {
        $ret = DBInstance::BackTransfer($message['data']['out_id']);
        $uid = $message['uid'];
        $data = $message['data'];
        $user = DBInstance::GetTableWords('user_register', 'bank,gold', ['uid' => $uid]);

        $message['data'] = [
            'bank'   => $user['bank'],
            'gold'   => $user['gold'],
            'status' => $ret ? 0 : 2,
        ];
        Common::SendToClient($message, $data['client_id']);

        if ($ret) {
            $data = ['bank' => $user['bank'], 'gold' => $user['gold']];
            $this->userInfo['bank'] = $data['bank'];
            Logic::SendRight($this->uid, 'Msg_Hall_ChangeGolds', $data);
        }
    }

    // ================================================================
    // 主流程: 一局游戏开始
    // ================================================================

    private function Msg_MJHLT_Start($message)
    {
        // -------- 1. 参数与校验 --------
        $betLevelIndex = $message['data']['score'] * $message['data']['double'];
        if ($betLevelIndex <= 0) {
            Logic::SendError($message['uid'], $message['event'], '等级错误');
            return;
        }
        if (empty(Logic::$betLevel[$betLevelIndex])) {
            $levelValues = array_values(Logic::$betLevel);
            Logic::$betLevel[$betLevelIndex] = !empty($levelValues) ? min($levelValues) : 1;
        }

        $use = ($this->free <= 0) ? ($message['data']['score'] * $message['data']['double'] * GAME_DOUBLE) : 0;

        if ($message['uid'] != $this->uid || $this->userInfo['gold'] < $use) {
            Logic::SendError($message['uid'], $message['event'], '无效操作');
            return;
        }

        $betMin = $this->roomRule['bet_min'] ?? 10000;
        $betMax = $this->roomRule['bet_max'] ?? 200000;
        if ($this->free <= 0 && ($use < $betMin || $use > $betMax)) {
            Logic::SendError($message['uid'], $message['event'], '投注金额超出范围');
            return;
        }

        // -------- 2. 免费档位与下注状态初始化 --------
        $this->prepareBetState($message['data']['score'], $message['data']['double'], $use);

        // -------- 3. 控制表读取 --------
        $logo_num = DBInstance::GetControlMap($this->uid, $this->roomRule['gtype'], $this->roomRule['level']);
        $level_index = $this->betGold * $this->betDouble;
        $control = $logo_num ? -2 : DBInstance::GetLBControl($this->uid, $this->roomRule['gtype'], Logic::$betLevel[$level_index]);
        $control_map = DBInstance::GetControlInfo('control_mjhlt', ['level' => $control]);

        $this->buildMapPossible($control, $control_map);

        // -------- 4. 免费下一转倒计时 --------
        if ($control >= 0) {
            $this->next_free_count--;
        }
        if (
            (isset($control_map[$control]['free_cirle']) && $this->next_free_count > $control_map[$control]['free_cirle'])
            || $use <= 0
            || $control < 0
        ) {
            $this->next_free_count = max($control_map[$control]['free_cirle'] ?? 0, 50);
        }

        // -------- 5. 免费轮参数 --------
        $is_free_round = ($this->free > 0 && $this->use > 0);
        $freeParams = $this->buildFreeRoundParams($is_free_round);

        // -------- 6. 生成地图 (最多 loop_max 次重摇) --------
        $loop_max = $this->calcLoopMax($is_free_round, $freeParams);
        $best = $this->rollMapLoop($loop_max, $is_free_round, $freeParams, $logo_num, $control);

        // 若爆奖模式未找到合格地图, 使用最佳结果兜底
        if ($is_free_round && $freeParams['need_boost'] && !$best['valid_found'] && $best['best_result'] !== null) {
            $this->map       = $best['best_map'];
            $this->deal_map  = $best['best_deal_map'];
            $this->cur_result= $best['best_result'];
            if ($freeParams['is_boom_round']) {
                $this->free_boom_used = true;
            }
        }

        // -------- 7. 兜底: 若最终结果仍超出限制, 清空本轮 --------
        $this->finalizeCurResult($is_free_round, $freeParams);

        // -------- 8. 结算新免费局 (进入新免费游戏时设置档位) --------
        if ($this->cur_result['getfree'] > 0 && $this->free <= 0) {
            $this->initFreePrizeLevel();
        }

        // -------- 9. 扣金币 / 发奖 / 写库 --------
        if ($this->free > 0) {
            $this->free--;
        }
        $this->free      += $this->cur_result['getfree'];
        $this->all_free  += $this->cur_result['getfree'];

        $user_win = array_sum($this->cur_result['score']);
        $this->all_win += $user_win - $use;
        $this->useGold($user_win - $use);

        Common::SyncPlatformPlayGame($this->uid, $use, $user_win, $this->roomRule['app_rid'] ?? '');

        $latest = DBInstance::GetTableWords('user_register', 'gold', ['uid' => $this->uid]);
        if ($latest && isset($latest['gold'])) {
            $this->userInfo['gold'] = $latest['gold'];
        }

        // 大奖评级
        $reward = 0;
        foreach (BIG_WIN as $key => $value) {
            if (intval($user_win / $this->use) >= $value) {
                $reward = $key;
                break;
            }
        }

        $this->all_score += $user_win;

        // -------- 10. 下发 --------
        $data = [
            'disappear'  => $this->cur_result['disappear'],
            'score'      => $this->cur_result['score'],
            'logo_info'  => $this->cur_result['logo_info'],
            'cur_gold'   => $this->cur_result['cur_gold'],
            'cur_time'   => $this->cur_result['cur_time'],
            'double_arr' => $this->cur_result['double_arr'],
            'free_logo'  => $this->cur_result['free_logo'],
            'curgrade'   => $this->betGold,
            'curdouble'  => $this->betDouble,
            'conscore'   => $use,
            'map'        => $this->map,
            'free'       => $this->free,
            'getfree'    => $this->cur_result['getfree'],
            'reward'     => $reward,
            'user_gold'  => $this->userInfo['gold'],
            'all_score'  => $this->all_score,
        ];

        $record_data = [
            'score'      => $this->cur_result['score'],
            'cur_gold'   => $this->cur_result['cur_gold'],
            'cur_time'   => $this->cur_result['cur_time'],
            'free_logo'  => $this->cur_result['free_logo'],
            'curgrade'   => $this->betGold,
            'curdouble'  => $this->betDouble,
            'conscore'   => $use,
            'free'       => $this->free,
            'getfree'    => $this->cur_result['getfree'],
            'reward'     => $reward,
            'all_score'  => $this->all_score,
        ];
        $this->save_maps[] = $record_data;

        // -------- 11. 免费保底计数 --------
        $this->updateGuaranteeState($use);

        Logic::SendRight($this->uid, 'Msg_MJHLT_Start', $data);

        // -------- 12. 后台统计 --------
        DBInstance::IncrementUserGet($this->uid, $user_win - $use);

        if (abs($control) != 2) {
            Logic::InsertProfit(Logic::$betLevel[$level_index], $user_win - $use);
        }

        if ($use) {
            $this->distime = count($this->map) - 1;
            $this->free_get = 0;
            $this->freedistime = 0;
        } else {
            $this->free_get += $user_win;
            $this->freedistime += count($this->map) - 1;
        }

        if ($this->free <= 0) {
            DBInstance::InsertGameRecord(
                $this->roomRule['gtype'],
                $this->roomRule['level'],
                $this->uid,
                $this->use,
                ($this->all_score - $this->use),
                $this->distime,
                $this->all_free,
                $this->save_maps,
                $this->freedistime
            );
        }

        $double = intval($user_win / $this->use);
        if ($user_win > HORSE['score'] && $double >= HORSE['double']) {
            Logic::HorseLamp($this->uid, $user_win, $double);
        }
    }

    // ================================================================
    // 子方法：Msg_MJHLT_Start 的拆解
    // ================================================================

    /**
     * 下注/免费状态准备
     */
    private function prepareBetState($new_bet_gold, $new_bet_double, $use)
    {
        if ($this->free > 0) {
            // 免费中: 不改动任何下注状态, 沿用进入免费时的档位
            return;
        }

        $this->all_score = 0;
        $this->all_free  = 0;
        $this->save_maps = [];

        // 注档变化时重置免费保底进度 (防止低注刷保底再跳高注)
        if (
            ($this->guarantee_bet_gold > 0 || $this->guarantee_bet_double > 0)
            && ($this->guarantee_bet_gold != $new_bet_gold || $this->guarantee_bet_double != $new_bet_double)
        ) {
            $this->normal_round_count = 0;
            $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
            $this->is_free_guarantee = false;
        }

        $this->guarantee_bet_gold = $new_bet_gold;
        $this->guarantee_bet_double = $new_bet_double;
        $this->betGold   = $new_bet_gold;
        $this->betDouble = $new_bet_double;
        $this->use = $new_bet_gold * $new_bet_double * GAME_DOUBLE;
    }

    /**
     * 根据控制表构造 mapPossible / wildPossible
     */
    private function buildMapPossible($control, $control_map)
    {
        $this->mapPossible  = [];
        $this->wildPossible = [];

        if ($this->free > 0 && !empty($control_map[$control]['free_map']) && is_array($control_map[$control]['free_map'])) {
            $this->mapPossible = $control_map[$control]['free_map'];
            for ($i = 0; $i < 5; $i++) {
                $this->wildPossible[$i] = ($i && isset($control_map[$control]['free_wild'])) ? $control_map[$control]['free_wild'][$i] : 0;
            }
        } elseif (empty($control_map[$control]) || !is_array($control_map[$control]['map'])) {
            for ($i = 0; $i < 5; $i++) {
                $this->mapPossible[$i]  = POSSIBLE;
                $this->wildPossible[$i] = mt_rand(1, 6) ? 20 : 0;
            }
        } else {
            $this->mapPossible = $control_map[$control]['map'];
            for ($i = 0; $i < 5; $i++) {
                $this->wildPossible[$i] = ($i && isset($control_map[$control]['wild'])) ? $control_map[$control]['wild'][$i] : 0;
            }
        }
    }

    /**
     * 免费轮参数构造
     */
    private function buildFreeRoundParams($is_free_round)
    {
        $params = [
            'max_score'        => PHP_INT_MAX,
            'total_max_score'  => PHP_INT_MAX,
            'total_left_score' => PHP_INT_MAX,
            'reroll_min_score' => 0,
            'total_min_score'  => 0,
            'total_need_score' => 0,
            'need_boost'       => false,
            'boost_min_score'  => 0,
            'boost_max_score'  => PHP_INT_MAX,
            'is_boom_round'    => false,
        ];

        if (!$is_free_round) {
            return $params;
        }

        // 进入免费时的档位设置
        if ($this->free_prize_level == FREE_LEVEL_NORMAL) {
            $max_double       = 15;
            $reroll_min_double = 2;
        } elseif ($this->free_prize_level == FREE_LEVEL_BIG) {
            $max_double       = 130;
            $reroll_min_double = 20;
        } else {
            $max_double       = 300;
            $reroll_min_double = 80;
        }

        $params['max_score']       = $this->use * $max_double;
        $params['total_max_score'] = $this->use * $this->free_total_limit_double;
        $params['total_left_score']= max(0, $params['total_max_score'] - $this->free_get);
        $params['reroll_min_score']= $this->use * $reroll_min_double;
        $params['total_min_score'] = $this->use * $this->free_total_min_double;
        $params['total_need_score']= max(0, $params['total_min_score'] - $this->free_get);

        // 当前这转是不是指定的爆奖转?
        if (!$this->free_boom_used && $this->free_boom_left_count > 0 && $this->free == $this->free_boom_left_count) {
            $params['is_boom_round']   = true;
            $params['need_boost']      = true;
            $params['boost_min_score'] = $this->use * $this->free_boom_min_double;
            $params['boost_max_score'] = $this->use * $this->free_boom_max_double;
            // 单次爆奖<?php

date_default_timezone_set('Asia/Shanghai');

use Workerman\Lib\Timer;

// ==================== 常量定义 ====================

define('ERTONG', 1);
define('ERTIAO', 2);
define('WUTONG', 3);
define('WUTIAO', 4);
define('BAWAN', 5);
define('BAIBAN', 6);
define('HONGZHONG', 7);
define('FACAI', 8);
define('SANTONG', 9);
define('FREE', 10);
define('BAIDA', 11);
define('GAME_DOUBLE', 20);

// 控制逻辑中引用的外部常量
defined('MAX_WIN_SCORE') || define('MAX_WIN_SCORE', 1000000);

// 不同图案连击的赔付倍率表 (3连/4连/5连)
define('DOUBLE', [
    ERTONG    => [3 => 1,  4 => 3,   5 => 6],
    ERTIAO    => [3 => 1,  4 => 3,   5 => 6],
    SANTONG   => [3 => 2,  4 => 4,   5 => 10],
    WUTONG    => [3 => 3,  4 => 5,   5 => 12],
    WUTIAO    => [3 => 3,  4 => 5,   5 => 12],
    BAWAN     => [3 => 5,  4 => 10,  5 => 15],
    BAIBAN    => [3 => 6,  4 => 15,  5 => 30],
    HONGZHONG => [3 => 8,  4 => 20,  5 => 40],
    FACAI     => [3 => 10, 4 => 25,  5 => 50],
]);

// 图案出现概率 (普通地图 / 免费地图)
define('POSSIBLE',      [ERTONG => 50, ERTIAO => 50, SANTONG => 50, WUTONG => 30, WUTIAO => 30, BAWAN => 15, BAIBAN => 7,  HONGZHONG => 3, FACAI => 1, FREE => 200]);
define('FREEPOSSIBLE',  [ERTONG => 50, ERTIAO => 50, SANTONG => 50, WUTONG => 30, WUTIAO => 30, BAWAN => 10, BAIBAN => 3,  HONGZHONG => 2, FACAI => 1, FREE => 8]);

// 大奖评级 (3=大/2=中/1=小)
define('BIG_WIN', [3 => 40, 2 => 20, 1 => 10]);

// Wild 柱阈值 (万分之 N)
define('WILD_PERCENT', 5000);

// 跑马灯触发条件
define('HORSE', ['double' => 20, 'score' => 1]);

// 免费游戏档位
define('FREE_LEVEL_NORMAL', 0);   // 普通
define('FREE_LEVEL_BIG',    1);   // 大奖/超级
define('FREE_LEVEL_JACKPOT',2);   // 爆奖


/**
 * 麻将/老虎机游戏主逻辑
 */
class Table
{
    // ==================== 玩家状态 ====================
    private $userInfo = [];
    private $uid = 0;
    private $free = 0;             // 剩余免费次数
    private $map = [];             // 地图 (各轮)
    private $betGold = 0;          // 当前下注档位
    private $betDouble = 1;        // 当前下注倍率
    private $roomRule = [];        // 房间配置
    private $use = 0;              // 实际消耗金币
    private $mTimer = 0;
    private $mapPossible = [];     // 当前地图概率表 (5列)
    private $wildPossible = [];    // Wild 出现概率 (5列)

    // ==================== 单局结算 ====================
    private $cur_result = [];
    private $deal_map = [];
    private $all_score = 0;        // 整局总得分
    private $all_free = 0;         // 整局获得的免费次数
    private $free_get = 0;         // 免费轮累计得分
    private $save_maps = [];
    private $distime = 0;
    private $freedistime = 0;
    private $next_free_count = 999;

    // ==================== 免费保底 ====================
    private $normal_round_count = 0;
    private $free_guarantee_threshold = 0;
    private $is_free_guarantee = false;
    private $free_guarantee_min = 150;
    private $free_guarantee_max = 250;

    // ==================== 免费游戏档位 ====================
    private $free_total_limit_double = 30;
    private $free_total_min_double = 0;
    private $free_prize_level = 0;
    private $force_free_trigger = false;

    private $free_boom_left_count = 0;   // 爆奖在剩余第几转出现
    private $free_boom_min_double = 0;
    private $free_boom_max_double = 0;
    private $free_boom_used = false;

    private $guarantee_bet_gold = 0;
    private $guarantee_bet_double = 0;
    private $guarantee_count = 0;

    // ==================== 胜负统计 ====================
    private $all_win = 0;


    // ================================================================
    // 构造与入口
    // ================================================================

    public function __construct($msg)
    {
        $this->roomRule = $msg;
        $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
        $this->resetCurResult();
    }

    public function All_RECV($message)
    {
        switch ($message['event']) {
            case 'Msg_MJHLT_Start':
                $this->Msg_MJHLT_Start($message);
                break;
            case 'Msg_Game_Out':
                $this->Msg_Game_Out($message);
                break;
            case 'Msg_Game_RoomInfo':
                $this->Msg_Game_RoomInfo($message);
                break;
            default:
                Logic::SendError($message['uid'], $message['event'], '');
                MyTools::msg('uid:' . $message['uid'] . '-----UnKnown!!!!!!!--------' . $message['event'], true);
                break;
        }
    }

    // ================================================================
    // 房间信息 / 进房 / 离线
    // ================================================================

    private function Msg_Game_RoomInfo($message)
    {
        if ($this->uid && $this->uid == $message['uid']) {
            Logic::SendRight($this->uid, 'Msg_Game_RoomInfo', [
                'free'         => $this->free,
                'all_score'    => $this->all_score,
                'all_free'     => $this->all_free,
                'curgrade'     => $this->betGold,
                'curdouble'    => $this->betDouble,
                'map'          => $this->map,
                'max_multiple' => max($this->roomRule['score_arr']),
                'level'        => $this->roomRule['level'],
                'score_arr'    => $this->roomRule['score_arr'],
                'double_arr'   => $this->roomRule['double_arr'],
                'base_arr'     => [GAME_DOUBLE],
                'min_gold'     => $this->roomRule['min_gold'],
                'max_gold'     => $this->roomRule['max_gold'],
                'bet_min'      => $this->roomRule['bet_min'] ?? 10000,
                'bet_max'      => $this->roomRule['bet_max'] ?? 200000,
                'gold'         => $this->userInfo['gold'],
            ]);
        } else {
            Logic::SendError($message['uid'], 'Msg_Game_RoomInfo', '无效操作');
        }
    }

    public function UserOnline($client_id, $uid)
    {
        Timer::del($this->mTimer);
        $this->Msg_Game_RoomInfo(['uid' => $uid]);
    }

    public function UserOff($uid)
    {
        $this->saveGameCache();
        $this->mTimer = Timer::add(60, function () {
            $this->Msg_Game_Out(['uid' => $this->uid]);
        }, [], false);
    }

    public function EnterRoom($msg)
    {
        $this->uid = $msg['uid'];
        $ret = DBInstance::GetGameCache($this->uid, $this->roomRule['gtype'], $this->roomRule['level']);

        if (!$ret) {
            $this->betGold   = min($this->roomRule['score_arr']);
            $this->betDouble = min($this->roomRule['double_arr']);
            DBInstance::InsertGameCache([
                'uid'        => $this->uid,
                'gtype'      => $this->roomRule['gtype'],
                'level'      => $this->roomRule['level'],
                'map'        => '[]',
                'bet_gold'   => $this->betGold,
                'bet_double' => $this->betDouble,
                'free'       => 0,
            ]);
            $this->guarantee_count = 0;
        } else {
            $this->map  = $ret['map'];
            $this->free = $ret['free'];

            if ($this->free > 0) {
                $this->betGold   = $ret['bet_gold'];
                $this->betDouble = $ret['bet_double'];
            } else {
                $this->betGold   = min($this->roomRule['score_arr']);
                $this->betDouble = min($this->roomRule['double_arr']);
            }

            $this->guarantee_count = $ret['vals']['guarantee_count'] ?? 0;
            $this->all_score       = $ret['vals']['all_score']       ?? 0;
            $this->all_free        = $ret['vals']['all_free']        ?? 0;
            $this->use             = $this->betGold * $this->betDouble * GAME_DOUBLE;

            if ($this->free) {
                $this->distime     = $ret['vals']['distime'];
                $this->free_get    = $ret['vals']['free_get'];
                $this->save_maps   = $ret['vals']['save_maps'];
                $this->freedistime = $ret['vals']['freedistime'];
            }
        }

        $this->map      = [];
        $this->deal_map = [];
        $this->resetCurResult();

        if ($this->free <= 0) {
            $this->free = 0;
            $this->normal_round_count = 0;
            $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
            $this->free_prize_level = 0;
            $this->free_total_limit_double = 30;
            $this->free_total_min_double = 0;
            $this->free_boom_left_count = 0;
            $this->free_boom_min_double = 0;
            $this->free_boom_max_double = 0;
            $this->free_boom_used = false;
        }

        $this->userInfo = $msg;
        $this->Msg_Game_RoomInfo(['uid' => $this->uid]);
    }

    public function DisRoom($msg = [])
    {
        $this->Msg_Game_Out(['uid' => $this->uid]);
    }

    // ================================================================
    // 退出/转账 (与主逻辑无关的基础设施)
    // ================================================================

    private function Msg_Game_Out($message)
    {
        Timer::del($this->mTimer);

        $gold = DBInstance::GetTableOneWord('user_register', 'gold', ['uid' => $this->uid]);
        $bank = DBInstance::GetTableOneWord('user_register', 'bank', ['uid' => $this->uid]);
        Logic::SendRight($this->uid, 'Msg_Game_Out', ['gold' => $gold, 'bank' => $bank]);

        $this->saveGameCache();

        $olddata = [
            'rid'     => $this->roomRule['rid'],
            'win'     => [],
            'palyers' => [$this->uid => $this->userInfo],
            'result'  => ['uid' => []],
            'gtype'   => $this->roomRule['gtype'],
        ];
        Logic::RoomOld($olddata);
    }

    public function ChangeGold($msg)
    {
        $uid = $msg['uid'];
        $before = DBInstance::GetUser(['uid' => $uid]);
        DBInstance::IncrementGolds('bank', $uid, $msg['data']['num']);
        DBInstance::InsertUserProfit($uid, $msg['data']['from'], $msg['data']['type'], $msg['data']['num'], $before);
        $data = DBInstance::GetTableWords('user_register', 'bank,gold', ['uid' => $uid]);
        $this->userInfo['bank'] = $data['bank'];
        Logic::SendRight($this->uid, 'Msg_Hall_ChangeGolds', $data);
    }

    public function BackTransfer($message)
    {
        $ret = DBInstance::BackTransfer($message['data']['out_id']);
        $uid = $message['uid'];
        $data = $message['data'];
        $user = DBInstance::GetTableWords('user_register', 'bank,gold', ['uid' => $uid]);

        $message['data'] = [
            'bank'   => $user['bank'],
            'gold'   => $user['gold'],
            'status' => $ret ? 0 : 2,
        ];
        Common::SendToClient($message, $data['client_id']);

        if ($ret) {
            $data = ['bank' => $user['bank'], 'gold' => $user['gold']];
            $this->userInfo['bank'] = $data['bank'];
            Logic::SendRight($this->uid, 'Msg_Hall_ChangeGolds', $data);
        }
    }

    // ================================================================
    // 主流程: 一局游戏开始
    // ================================================================

    private function Msg_MJHLT_Start($message)
    {
        // -------- 1. 参数与校验 --------
        $betLevelIndex = $message['data']['score'] * $message['data']['double'];
        if ($betLevelIndex <= 0) {
            Logic::SendError($message['uid'], $message['event'], '等级错误');
            return;
        }
        if (empty(Logic::$betLevel[$betLevelIndex])) {
            $levelValues = array_values(Logic::$betLevel);
            Logic::$betLevel[$betLevelIndex] = !empty($levelValues) ? min($levelValues) : 1;
        }

        $use = ($this->free <= 0) ? ($message['data']['score'] * $message['data']['double'] * GAME_DOUBLE) : 0;

        if ($message['uid'] != $this->uid || $this->userInfo['gold'] < $use) {
            Logic::SendError($message['uid'], $message['event'], '无效操作');
            return;
        }

        $betMin = $this->roomRule['bet_min'] ?? 10000;
        $betMax = $this->roomRule['bet_max'] ?? 200000;
        if ($this->free <= 0 && ($use < $betMin || $use > $betMax)) {
            Logic::SendError($message['uid'], $message['event'], '投注金额超出范围');
            return;
        }

        // -------- 2. 免费档位与下注状态初始化 --------
        $this->prepareBetState($message['data']['score'], $message['data']['double'], $use);

        // -------- 3. 控制表读取 --------
        $logo_num = DBInstance::GetControlMap($this->uid, $this->roomRule['gtype'], $this->roomRule['level']);
        $level_index = $this->betGold * $this->betDouble;
        $control = $logo_num ? -2 : DBInstance::GetLBControl($this->uid, $this->roomRule['gtype'], Logic::$betLevel[$level_index]);
        $control_map = DBInstance::GetControlInfo('control_mjhlt', ['level' => $control]);

        $this->buildMapPossible($control, $control_map);

        // -------- 4. 免费下一转倒计时 --------
        if ($control >= 0) {
            $this->next_free_count--;
        }
        if (
            (isset($control_map[$control]['free_cirle']) && $this->next_free_count > $control_map[$control]['free_cirle'])
            || $use <= 0
            || $control < 0
        ) {
            $this->next_free_count = max($control_map[$control]['free_cirle'] ?? 0, 50);
        }

        // -------- 5. 免费轮参数 --------
        $is_free_round = ($this->free > 0 && $this->use > 0);
        $freeParams = $this->buildFreeRoundParams($is_free_round);

        // -------- 6. 生成地图 (最多 loop_max 次重摇) --------
        $loop_max = $this->calcLoopMax($is_free_round, $freeParams);
        $best = $this->rollMapLoop($loop_max, $is_free_round, $freeParams, $logo_num, $control);

        // 若爆奖模式未找到合格地图, 使用最佳结果兜底
        if ($is_free_round && $freeParams['need_boost'] && !$best['valid_found'] && $best['best_result'] !== null) {
            $this->map       = $best['best_map'];
            $this->deal_map  = $best['best_deal_map'];
            $this->cur_result= $best['best_result'];
            if ($freeParams['is_boom_round']) {
                $this->free_boom_used = true;
            }
        }

        // -------- 7. 兜底: 若最终结果仍超出限制, 清空本轮 --------
        $this->finalizeCurResult($is_free_round, $freeParams);

        // -------- 8. 结算新免费局 (进入新免费游戏时设置档位) --------
        if ($this->cur_result['getfree'] > 0 && $this->free <= 0) {
            $this->initFreePrizeLevel();
        }

        // -------- 9. 扣金币 / 发奖 / 写库 --------
        if ($this->free > 0) {
            $this->free--;
        }
        $this->free      += $this->cur_result['getfree'];
        $this->all_free  += $this->cur_result['getfree'];

        $user_win = array_sum($this->cur_result['score']);
        $this->all_win += $user_win - $use;
        $this->useGold($user_win - $use);

        Common::SyncPlatformPlayGame($this->uid, $use, $user_win, $this->roomRule['app_rid'] ?? '');

        $latest = DBInstance::GetTableWords('user_register', 'gold', ['uid' => $this->uid]);
        if ($latest && isset($latest['gold'])) {
            $this->userInfo['gold'] = $latest['gold'];
        }

        // 大奖评级
        $reward = 0;
        foreach (BIG_WIN as $key => $value) {
            if (intval($user_win / $this->use) >= $value) {
                $reward = $key;
                break;
            }
        }

        $this->all_score += $user_win;

        // -------- 10. 下发 --------
        $data = [
            'disappear'  => $this->cur_result['disappear'],
            'score'      => $this->cur_result['score'],
            'logo_info'  => $this->cur_result['logo_info'],
            'cur_gold'   => $this->cur_result['cur_gold'],
            'cur_time'   => $this->cur_result['cur_time'],
            'double_arr' => $this->cur_result['double_arr'],
            'free_logo'  => $this->cur_result['free_logo'],
            'curgrade'   => $this->betGold,
            'curdouble'  => $this->betDouble,
            'conscore'   => $use,
            'map'        => $this->map,
            'free'       => $this->free,
            'getfree'    => $this->cur_result['getfree'],
            'reward'     => $reward,
            'user_gold'  => $this->userInfo['gold'],
            'all_score'  => $this->all_score,
        ];

        $record_data = [
            'score'      => $this->cur_result['score'],
            'cur_gold'   => $this->cur_result['cur_gold'],
            'cur_time'   => $this->cur_result['cur_time'],
            'free_logo'  => $this->cur_result['free_logo'],
            'curgrade'   => $this->betGold,
            'curdouble'  => $this->betDouble,
            'conscore'   => $use,
            'free'       => $this->free,
            'getfree'    => $this->cur_result['getfree'],
            'reward'     => $reward,
            'all_score'  => $this->all_score,
        ];
        $this->save_maps[] = $record_data;

        // -------- 11. 免费保底计数 --------
        $this->updateGuaranteeState($use);

        Logic::SendRight($this->uid, 'Msg_MJHLT_Start', $data);

        // -------- 12. 后台统计 --------
        DBInstance::IncrementUserGet($this->uid, $user_win - $use);

        if (abs($control) != 2) {
            Logic::InsertProfit(Logic::$betLevel[$level_index], $user_win - $use);
        }

        if ($use) {
            $this->distime = count($this->map) - 1;
            $this->free_get = 0;
            $this->freedistime = 0;
        } else {
            $this->free_get += $user_win;
            $this->freedistime += count($this->map) - 1;
        }

        if ($this->free <= 0) {
            DBInstance::InsertGameRecord(
                $this->roomRule['gtype'],
                $this->roomRule['level'],
                $this->uid,
                $this->use,
                ($this->all_score - $this->use),
                $this->distime,
                $this->all_free,
                $this->save_maps,
                $this->freedistime
            );
        }

        $double = intval($user_win / $this->use);
        if ($user_win > HORSE['score'] && $double >= HORSE['double']) {
            Logic::HorseLamp($this->uid, $user_win, $double);
        }
    }

    // ================================================================
    // 子方法：Msg_MJHLT_Start 的拆解
    // ================================================================

    /**
     * 下注/免费状态准备
     */
    private function prepareBetState($new_bet_gold, $new_bet_double, $use)
    {
        if ($this->free > 0) {
            // 免费中: 不改动任何下注状态, 沿用进入免费时的档位
            return;
        }

        $this->all_score = 0;
        $this->all_free  = 0;
        $this->save_maps = [];

        // 注档变化时重置免费保底进度 (防止低注刷保底再跳高注)
        if (
            ($this->guarantee_bet_gold > 0 || $this->guarantee_bet_double > 0)
            && ($this->guarantee_bet_gold != $new_bet_gold || $this->guarantee_bet_double != $new_bet_double)
        ) {
            $this->normal_round_count = 0;
            $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
            $this->is_free_guarantee = false;
        }

        $this->guarantee_bet_gold = $new_bet_gold;
        $this->guarantee_bet_double = $new_bet_double;
        $this->betGold   = $new_bet_gold;
        $this->betDouble = $new_bet_double;
        $this->use = $new_bet_gold * $new_bet_double * GAME_DOUBLE;
    }

    /**
     * 根据控制表构造 mapPossible / wildPossible
     */
    private function buildMapPossible($control, $control_map)
    {
        $this->mapPossible  = [];
        $this->wildPossible = [];

        if ($this->free > 0 && !empty($control_map[$control]['free_map']) && is_array($control_map[$control]['free_map'])) {
            $this->mapPossible = $control_map[$control]['free_map'];
            for ($i = 0; $i < 5; $i++) {
                $this->wildPossible[$i] = ($i && isset($control_map[$control]['free_wild'])) ? $control_map[$control]['free_wild'][$i] : 0;
            }
        } elseif (empty($control_map[$control]) || !is_array($control_map[$control]['map'])) {
            for ($i = 0; $i < 5; $i++) {
                $this->mapPossible[$i]  = POSSIBLE;
                $this->wildPossible[$i] = mt_rand(1, 6) ? 20 : 0;
            }
        } else {
            $this->mapPossible = $control_map[$control]['map'];
            for ($i = 0; $i < 5; $i++) {
                $this->wildPossible[$i] = ($i && isset($control_map[$control]['wild'])) ? $control_map[$control]['wild'][$i] : 0;
            }
        }
    }

    /**
     * 免费轮参数构造
     */
    private function buildFreeRoundParams($is_free_round)
    {
        $params = [
            'max_score'        => PHP_INT_MAX,
            'total_max_score'  => PHP_INT_MAX,
            'total_left_score' => PHP_INT_MAX,
            'reroll_min_score' => 0,
            'total_min_score'  => 0,
            'total_need_score' => 0,
            'need_boost'       => false,
            'boost_min_score'  => 0,
            'boost_max_score'  => PHP_INT_MAX,
            'is_boom_round'    => false,
        ];

        if (!$is_free_round) {
            return $params;
        }

        // 进入免费时的档位设置
        if ($this->free_prize_level == FREE_LEVEL_NORMAL) {
            $max_double       = 15;
            $reroll_min_double = 2;
        } elseif ($this->free_prize_level == FREE_LEVEL_BIG) {
            $max_double       = 130;
            $reroll_min_double = 20;
        } else {
            $max_double       = 300;
            $reroll_min_double = 80;
        }

        $params['max_score']       = $this->use * $max_double;
        $params['total_max_score'] = $this->use * $this->free_total_limit_double;
        $params['total_left_score']= max(0, $params['total_max_score'] - $this->free_get);
        $params['reroll_min_score']= $this->use * $reroll_min_double;
        $params['total_min_score'] = $this->use * $this->free_total_min_double;
        $params['total_need_score']= max(0, $params['total_min_score'] - $this->free_get);

        // 当前这转是不是指定的爆奖转?
        if (!$this->free_boom_used && $this->free_boom_left_count > 0 && $this->free == $this->free_boom_left_count) {
            $params['is_boom_round']   = true;
            $params['need_boost']      = true;
            $params['boost_min_score'] = $this->use * $this->free_boom_min_double;
            $params['boost_max_score'] = $this->use * $this->free_boom_max_double;
            // 单次爆奖不能超过本轮总剩余额度
            $params['boost_max_score'] = min($params['<?php

date_default_timezone_set('Asia/Shanghai');

use Workerman\Lib\Timer;

// ==================== 常量定义 ====================

define('ERTONG', 1);
define('ERTIAO', 2);
define('WUTONG', 3);
define('WUTIAO', 4);
define('BAWAN', 5);
define('BAIBAN', 6);
define('HONGZHONG', 7);
define('FACAI', 8);
define('SANTONG', 9);
define('FREE', 10);
define('BAIDA', 11);
define('GAME_DOUBLE', 20);

// 控制逻辑中引用的外部常量
defined('MAX_WIN_SCORE') || define('MAX_WIN_SCORE', 1000000);

// 不同图案连击的赔付倍率表 (3连/4连/5连)
define('DOUBLE', [
    ERTONG    => [3 => 1,  4 => 3,   5 => 6],
    ERTIAO    => [3 => 1,  4 => 3,   5 => 6],
    SANTONG   => [3 => 2,  4 => 4,   5 => 10],
    WUTONG    => [3 => 3,  4 => 5,   5 => 12],
    WUTIAO    => [3 => 3,  4 => 5,   5 => 12],
    BAWAN     => [3 => 5,  4 => 10,  5 => 15],
    BAIBAN    => [3 => 6,  4 => 15,  5 => 30],
    HONGZHONG => [3 => 8,  4 => 20,  5 => 40],
    FACAI     => [3 => 10, 4 => 25,  5 => 50],
]);

// 图案出现概率 (普通地图 / 免费地图)
define('POSSIBLE',      [ERTONG => 50, ERTIAO => 50, SANTONG => 50, WUTONG => 30, WUTIAO => 30, BAWAN => 15, BAIBAN => 7,  HONGZHONG => 3, FACAI => 1, FREE => 200]);
define('FREEPOSSIBLE',  [ERTONG => 50, ERTIAO => 50, SANTONG => 50, WUTONG => 30, WUTIAO => 30, BAWAN => 10, BAIBAN => 3,  HONGZHONG => 2, FACAI => 1, FREE => 8]);

// 大奖评级 (3=大/2=中/1=小)
define('BIG_WIN', [3 => 40, 2 => 20, 1 => 10]);

// Wild 柱阈值 (万分之 N)
define('WILD_PERCENT', 5000);

// 跑马灯触发条件
define('HORSE', ['double' => 20, 'score' => 1]);

// 免费游戏档位
define('FREE_LEVEL_NORMAL', 0);   // 普通
define('FREE_LEVEL_BIG',    1);   // 大奖/超级
define('FREE_LEVEL_JACKPOT',2);   // 爆奖


/**
 * 麻将/老虎机游戏主逻辑
 */
class Table
{
    // ==================== 玩家状态 ====================
    private $userInfo = [];
    private $uid = 0;
    private $free = 0;             // 剩余免费次数
    private $map = [];             // 地图 (各轮)
    private $betGold = 0;          // 当前下注档位
    private $betDouble = 1;        // 当前下注倍率
    private $roomRule = [];        // 房间配置
    private $use = 0;              // 实际消耗金币
    private $mTimer = 0;
    private $mapPossible = [];     // 当前地图概率表 (5列)
    private $wildPossible = [];    // Wild 出现概率 (5列)

    // ==================== 单局结算 ====================
    private $cur_result = [];
    private $deal_map = [];
    private $all_score = 0;        // 整局总得分
    private $all_free = 0;         // 整局获得的免费次数
    private $free_get = 0;         // 免费轮累计得分
    private $save_maps = [];
    private $distime = 0;
    private $freedistime = 0;
    private $next_free_count = 999;

    // ==================== 免费保底 ====================
    private $normal_round_count = 0;
    private $free_guarantee_threshold = 0;
    private $is_free_guarantee = false;
    private $free_guarantee_min = 150;
    private $free_guarantee_max = 250;

    // ==================== 免费游戏档位 ====================
    private $free_total_limit_double = 30;
    private $free_total_min_double = 0;
    private $free_prize_level = 0;
    private $force_free_trigger = false;

    private $free_boom_left_count = 0;   // 爆奖在剩余第几转出现
    private $free_boom_min_double = 0;
    private $free_boom_max_double = 0;
    private $free_boom_used = false;

    private $guarantee_bet_gold = 0;
    private $guarantee_bet_double = 0;
    private $guarantee_count = 0;

    // ==================== 胜负统计 ====================
    private $all_win = 0;


    // ================================================================
    // 构造与入口
    // ================================================================

    public function __construct($msg)
    {
        $this->roomRule = $msg;
        $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
        $this->resetCurResult();
    }

    public function All_RECV($message)
    {
        switch ($message['event']) {
            case 'Msg_MJHLT_Start':
                $this->Msg_MJHLT_Start($message);
                break;
            case 'Msg_Game_Out':
                $this->Msg_Game_Out($message);
                break;
            case 'Msg_Game_RoomInfo':
                $this->Msg_Game_RoomInfo($message);
                break;
            default:
                Logic::SendError($message['uid'], $message['event'], '');
                MyTools::msg('uid:' . $message['uid'] . '-----UnKnown!!!!!!!--------' . $message['event'], true);
                break;
        }
    }

    // ================================================================
    // 房间信息 / 进房 / 离线
    // ================================================================

    private function Msg_Game_RoomInfo($message)
    {
        if ($this->uid && $this->uid == $message['uid']) {
            Logic::SendRight($this->uid, 'Msg_Game_RoomInfo', [
                'free'         => $this->free,
                'all_score'    => $this->all_score,
                'all_free'     => $this->all_free,
                'curgrade'     => $this->betGold,
                'curdouble'    => $this->betDouble,
                'map'          => $this->map,
                'max_multiple' => max($this->roomRule['score_arr']),
                'level'        => $this->roomRule['level'],
                'score_arr'    => $this->roomRule['score_arr'],
                'double_arr'   => $this->roomRule['double_arr'],
                'base_arr'     => [GAME_DOUBLE],
                'min_gold'     => $this->roomRule['min_gold'],
                'max_gold'     => $this->roomRule['max_gold'],
                'bet_min'      => $this->roomRule['bet_min'] ?? 10000,
                'bet_max'      => $this->roomRule['bet_max'] ?? 200000,
                'gold'         => $this->userInfo['gold'],
            ]);
        } else {
            Logic::SendError($message['uid'], 'Msg_Game_RoomInfo', '无效操作');
        }
    }

    public function UserOnline($client_id, $uid)
    {
        Timer::del($this->mTimer);
        $this->Msg_Game_RoomInfo(['uid' => $uid]);
    }

    public function UserOff($uid)
    {
        $this->saveGameCache();
        $this->mTimer = Timer::add(60, function () {
            $this->Msg_Game_Out(['uid' => $this->uid]);
        }, [], false);
    }

    public function EnterRoom($msg)
    {
        $this->uid = $msg['uid'];
        $ret = DBInstance::GetGameCache($this->uid, $this->roomRule['gtype'], $this->roomRule['level']);

        if (!$ret) {
            $this->betGold   = min($this->roomRule['score_arr']);
            $this->betDouble = min($this->roomRule['double_arr']);
            DBInstance::InsertGameCache([
                'uid'        => $this->uid,
                'gtype'      => $this->roomRule['gtype'],
                'level'      => $this->roomRule['level'],
                'map'        => '[]',
                'bet_gold'   => $this->betGold,
                'bet_double' => $this->betDouble,
                'free'       => 0,
            ]);
            $this->guarantee_count = 0;
        } else {
            $this->map  = $ret['map'];
            $this->free = $ret['free'];

            if ($this->free > 0) {
                $this->betGold   = $ret['bet_gold'];
                $this->betDouble = $ret['bet_double'];
            } else {
                $this->betGold   = min($this->roomRule['score_arr']);
                $this->betDouble = min($this->roomRule['double_arr']);
            }

            $this->guarantee_count = $ret['vals']['guarantee_count'] ?? 0;
            $this->all_score       = $ret['vals']['all_score']       ?? 0;
            $this->all_free        = $ret['vals']['all_free']        ?? 0;
            $this->use             = $this->betGold * $this->betDouble * GAME_DOUBLE;

            if ($this->free) {
                $this->distime     = $ret['vals']['distime'];
                $this->free_get    = $ret['vals']['free_get'];
                $this->save_maps   = $ret['vals']['save_maps'];
                $this->freedistime = $ret['vals']['freedistime'];
            }
        }

        $this->map      = [];
        $this->deal_map = [];
        $this->resetCurResult();

        if ($this->free <= 0) {
            $this->free = 0;
            $this->normal_round_count = 0;
            $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
            $this->free_prize_level = 0;
            $this->free_total_limit_double = 30;
            $this->free_total_min_double = 0;
            $this->free_boom_left_count = 0;
            $this->free_boom_min_double = 0;
            $this->free_boom_max_double = 0;
            $this->free_boom_used = false;
        }

        $this->userInfo = $msg;
        $this->Msg_Game_RoomInfo(['uid' => $this->uid]);
    }

    public function DisRoom($msg = [])
    {
        $this->Msg_Game_Out(['uid' => $this->uid]);
    }

    // ================================================================
    // 退出/转账 (与主逻辑无关的基础设施)
    // ================================================================

    private function Msg_Game_Out($message)
    {
        Timer::del($this->mTimer);

        $gold = DBInstance::GetTableOneWord('user_register', 'gold', ['uid' => $this->uid]);
        $bank = DBInstance::GetTableOneWord('user_register', 'bank', ['uid' => $this->uid]);
        Logic::SendRight($this->uid, 'Msg_Game_Out', ['gold' => $gold, 'bank' => $bank]);

        $this->saveGameCache();

        $olddata = [
            'rid'     => $this->roomRule['rid'],
            'win'     => [],
            'palyers' => [$this->uid => $this->userInfo],
            'result'  => ['uid' => []],
            'gtype'   => $this->roomRule['gtype'],
        ];
        Logic::RoomOld($olddata);
    }

    public function ChangeGold($msg)
    {
        $uid = $msg['uid'];
        $before = DBInstance::GetUser(['uid' => $uid]);
        DBInstance::IncrementGolds('bank', $uid, $msg['data']['num']);
        DBInstance::InsertUserProfit($uid, $msg['data']['from'], $msg['data']['type'], $msg['data']['num'], $before);
        $data = DBInstance::GetTableWords('user_register', 'bank,gold', ['uid' => $uid]);
        $this->userInfo['bank'] = $data['bank'];
        Logic::SendRight($this->uid, 'Msg_Hall_ChangeGolds', $data);
    }

    public function BackTransfer($message)
    {
        $ret = DBInstance::BackTransfer($message['data']['out_id']);
        $uid = $message['uid'];
        $data = $message['data'];
        $user = DBInstance::GetTableWords('user_register', 'bank,gold', ['uid' => $uid]);

        $message['data'] = [
            'bank'   => $user['bank'],
            'gold'   => $user['gold'],
            'status' => $ret ? 0 : 2,
        ];
        Common::SendToClient($message, $data['client_id']);

        if ($ret) {
            $data = ['bank' => $user['bank'], 'gold' => $user['gold']];
            $this->userInfo['bank'] = $data['bank'];
            Logic::SendRight($this->uid, 'Msg_Hall_ChangeGolds', $data);
        }
    }

    // ================================================================
    // 主流程: 一局游戏开始
    // ================================================================

    private function Msg_MJHLT_Start($message)
    {
        // -------- 1. 参数与校验 --------
        $betLevelIndex = $message['data']['score'] * $message['data']['double'];
        if ($betLevelIndex <= 0) {
            Logic::SendError($message['uid'], $message['event'], '等级错误');
            return;
        }
        if (empty(Logic::$betLevel[$betLevelIndex])) {
            $levelValues = array_values(Logic::$betLevel);
            Logic::$betLevel[$betLevelIndex] = !empty($levelValues) ? min($levelValues) : 1;
        }

        $use = ($this->free <= 0) ? ($message['data']['score'] * $message['data']['double'] * GAME_DOUBLE) : 0;

        if ($message['uid'] != $this->uid || $this->userInfo['gold'] < $use) {
            Logic::SendError($message['uid'], $message['event'], '无效操作');
            return;
        }

        $betMin = $this->roomRule['bet_min'] ?? 10000;
        $betMax = $this->roomRule['bet_max'] ?? 200000;
        if ($this->free <= 0 && ($use < $betMin || $use > $betMax)) {
            Logic::SendError($message['uid'], $message['event'], '投注金额超出范围');
            return;
        }

        // -------- 2. 免费档位与下注状态初始化 --------
        $this->prepareBetState($message['data']['score'], $message['data']['double'], $use);

        // -------- 3. 控制表读取 --------
        $logo_num = DBInstance::GetControlMap($this->uid, $this->roomRule['gtype'], $this->roomRule['level']);
        $level_index = $this->betGold * $this->betDouble;
        $control = $logo_num ? -2 : DBInstance::GetLBControl($this->uid, $this->roomRule['gtype'], Logic::$betLevel[$level_index]);
        $control_map = DBInstance::GetControlInfo('control_mjhlt', ['level' => $control]);

        $this->buildMapPossible($control, $control_map);

        // -------- 4. 免费下一转倒计时 --------
        if ($control >= 0) {
            $this->next_free_count--;
        }
        if (
            (isset($control_map[$control]['free_cirle']) && $this->next_free_count > $control_map[$control]['free_cirle'])
            || $use <= 0
            || $control < 0
        ) {
            $this->next_free_count = max($control_map[$control]['free_cirle'] ?? 0, 50);
        }

        // -------- 5. 免费轮参数 --------
        $is_free_round = ($this->free > 0 && $this->use > 0);
        $freeParams = $this->buildFreeRoundParams($is_free_round);

        // -------- 6. 生成地图 (最多 loop_max 次重摇) --------
        $loop_max = $this->calcLoopMax($is_free_round, $freeParams);
        $best = $this->rollMapLoop($loop_max, $is_free_round, $freeParams, $logo_num, $control);

        // 若爆奖模式未找到合格地图, 使用最佳结果兜底
        if ($is_free_round && $freeParams['need_boost'] && !$best['valid_found'] && $best['best_result'] !== null) {
            $this->map       = $best['best_map'];
            $this->deal_map  = $best['best_deal_map'];
            $this->cur_result= $best['best_result'];
            if ($freeParams['is_boom_round']) {
                $this->free_boom_used = true;
            }
        }

        // -------- 7. 兜底: 若最终结果仍超出限制, 清空本轮 --------
        $this->finalizeCurResult($is_free_round, $freeParams);

        // -------- 8. 结算新免费局 (进入新免费游戏时设置档位) --------
        if ($this->cur_result['getfree'] > 0 && $this->free <= 0) {
            $this->initFreePrizeLevel();
        }

        // -------- 9. 扣金币 / 发奖 / 写库 --------
        if ($this->free > 0) {
            $this->free--;
        }
        $this->free      += $this->cur_result['getfree'];
        $this->all_free  += $this->cur_result['getfree'];

        $user_win = array_sum($this->cur_result['score']);
        $this->all_win += $user_win - $use;
        $this->useGold($user_win - $use);

        Common::SyncPlatformPlayGame($this->uid, $use, $user_win, $this->roomRule['app_rid'] ?? '');

        $latest = DBInstance::GetTableWords('user_register', 'gold', ['uid' => $this->uid]);
        if ($latest && isset($latest['gold'])) {
            $this->userInfo['gold'] = $latest['gold'];
        }

        // 大奖评级
        $reward = 0;
        foreach (BIG_WIN as $key => $value) {
            if (intval($user_win / $this->use) >= $value) {
                $reward = $key;
                break;
            }
        }

        $this->all_score += $user_win;

        // -------- 10. 下发 --------
        $data = [
            'disappear'  => $this->cur_result['disappear'],
            'score'      => $this->cur_result['score'],
            'logo_info'  => $this->cur_result['logo_info'],
            'cur_gold'   => $this->cur_result['cur_gold'],
            'cur_time'   => $this->cur_result['cur_time'],
            'double_arr' => $this->cur_result['double_arr'],
            'free_logo'  => $this->cur_result['free_logo'],
            'curgrade'   => $this->betGold,
            'curdouble'  => $this->betDouble,
            'conscore'   => $use,
            'map'        => $this->map,
            'free'       => $this->free,
            'getfree'    => $this->cur_result['getfree'],
            'reward'     => $reward,
            'user_gold'  => $this->userInfo['gold'],
            'all_score'  => $this->all_score,
        ];

        $record_data = [
            'score'      => $this->cur_result['score'],
            'cur_gold'   => $this->cur_result['cur_gold'],
            'cur_time'   => $this->cur_result['cur_time'],
            'free_logo'  => $this->cur_result['free_logo'],
            'curgrade'   => $this->betGold,
            'curdouble'  => $this->betDouble,
            'conscore'   => $use,
            'free'       => $this->free,
            'getfree'    => $this->cur_result['getfree'],
            'reward'     => $reward,
            'all_score'  => $this->all_score,
        ];
        $this->save_maps[] = $record_data;

        // -------- 11. 免费保底计数 --------
        $this->updateGuaranteeState($use);

        Logic::SendRight($this->uid, 'Msg_MJHLT_Start', $data);

        // -------- 12. 后台统计 --------
        DBInstance::IncrementUserGet($this->uid, $user_win - $use);

        if (abs($control) != 2) {
            Logic::InsertProfit(Logic::$betLevel[$level_index], $user_win - $use);
        }

        if ($use) {
            $this->distime = count($this->map) - 1;
            $this->free_get = 0;
            $this->freedistime = 0;
        } else {
            $this->free_get += $user_win;
            $this->freedistime += count($this->map) - 1;
        }

        if ($this->free <= 0) {
            DBInstance::InsertGameRecord(
                $this->roomRule['gtype'],
                $this->roomRule['level'],
                $this->uid,
                $this->use,
                ($this->all_score - $this->use),
                $this->distime,
                $this->all_free,
                $this->save_maps,
                $this->freedistime
            );
        }

        $double = intval($user_win / $this->use);
        if ($user_win > HORSE['score'] && $double >= HORSE['double']) {
            Logic::HorseLamp($this->uid, $user_win, $double);
        }
    }

    // ================================================================
    // 子方法：Msg_MJHLT_Start 的拆解
    // ================================================================

    /**
     * 下注/免费状态准备
     */
    private function prepareBetState($new_bet_gold, $new_bet_double, $use)
    {
        if ($this->free > 0) {
            // 免费中: 不改动任何下注状态, 沿用进入免费时的档位
            return;
        }

        $this->all_score = 0;
        $this->all_free  = 0;
        $this->save_maps = [];

        // 注档变化时重置免费保底进度 (防止低注刷保底再跳高注)
        if (
            ($this->guarantee_bet_gold > 0 || $this->guarantee_bet_double > 0)
            && ($this->guarantee_bet_gold != $new_bet_gold || $this->guarantee_bet_double != $new_bet_double)
        ) {
            $this->normal_round_count = 0;
            $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
            $this->is_free_guarantee = false;
        }

        $this->guarantee_bet_gold = $new_bet_gold;
        $this->guarantee_bet_double = $new_bet_double;
        $this->betGold   = $new_bet_gold;
        $this->betDouble = $new_bet_double;
        $this->use = $new_bet_gold * $new_bet_double * GAME_DOUBLE;
    }

    /**
     * 根据控制表构造 mapPossible / wildPossible
     */
    private function buildMapPossible($control, $control_map)
    {
        $this->mapPossible  = [];
        $this->wildPossible = [];

        if ($this->free > 0 && !empty($control_map[$control]['free_map']) && is_array($control_map[$control]['free_map'])) {
            $this->mapPossible = $control_map[$control]['free_map'];
            for ($i = 0; $i < 5; $i++) {
                $this->wildPossible[$i] = ($i && isset($control_map[$control]['free_wild'])) ? $control_map[$control]['free_wild'][$i] : 0;
            }
        } elseif (empty($control_map[$control]) || !is_array($control_map[$control]['map'])) {
            for ($i = 0; $i < 5; $i++) {
                $this->mapPossible[$i]  = POSSIBLE;
                $this->wildPossible[$i] = mt_rand(1, 6) ? 20 : 0;
            }
        } else {
            $this->mapPossible = $control_map[$control]['map'];
            for ($i = 0; $i < 5; $i++) {
                $this->wildPossible[$i] = ($i && isset($control_map[$control]['wild'])) ? $control_map[$control]['wild'][$i] : 0;
            }
        }
    }

    /**
     * 免费轮参数构造
     */
    private function buildFreeRoundParams($is_free_round)
    {
        $params = [
            'max_score'        => PHP_INT_MAX,
            'total_max_score'  => PHP_INT_MAX,
            'total_left_score' => PHP_INT_MAX,
            'reroll_min_score' => 0,
            'total_min_score'  => 0,
            'total_need_score' => 0,
            'need_boost'       => false,
            'boost_min_score'  => 0,
            'boost_max_score'  => PHP_INT_MAX,
            'is_boom_round'    => false,
        ];

        if (!$is_free_round) {
            return $params;
        }

        // 进入免费时的档位设置
        if ($this->free_prize_level == FREE_LEVEL_NORMAL) {
            $max_double       = 15;
            $reroll_min_double = 2;
        } elseif ($this->free_prize_level == FREE_LEVEL_BIG) {
            $max_double       = 130;
            $reroll_min_double = 20;
        } else {
            $max_double       = 300;
            $reroll_min_double = 80;
        }

        $params['max_score']       = $this->use * $max_double;
        $params['total_max_score'] = $this->use * $this->free_total_limit_double;
        $params['total_left_score']= max(0, $params['total_max_score'] - $this->free_get);
        $params['reroll_min_score']= $this->use * $reroll_min_double;
        $params['total_min_score'] = $this->use * $this->free_total_min_double;
        $params['total_need_score']= max(0, $params['total_min_score'] - $this->free_get);

        // 当前这转是不是指定的爆奖转?
        if (!$this->free_boom_used && $this->free_boom_left_count > 0 && $this->free == $this->free_boom_left_count) {
            $params['is_boom_round']   = true;
            $params['need_boost']      = true;
            $params['boost_min_score'] = $this->use * $this->free_boom_min_double;
            $params['boost_max_score'] = $this->use * $this->free_boom_max_double;
            // 单次爆奖不能超过本轮总剩余额度
            $params['boost_max_score'] = min($params['boost_max_score'], $params['total_left_score']);
            // 如果剩余额度低于爆<?php

date_default_timezone_set('Asia/Shanghai');

use Workerman\Lib\Timer;

// ==================== 常量定义 ====================

define('ERTONG', 1);
define('ERTIAO', 2);
define('WUTONG', 3);
define('WUTIAO', 4);
define('BAWAN', 5);
define('BAIBAN', 6);
define('HONGZHONG', 7);
define('FACAI', 8);
define('SANTONG', 9);
define('FREE', 10);
define('BAIDA', 11);
define('GAME_DOUBLE', 20);

// 控制逻辑中引用的外部常量
defined('MAX_WIN_SCORE') || define('MAX_WIN_SCORE', 1000000);

// 不同图案连击的赔付倍率表 (3连/4连/5连)
define('DOUBLE', [
    ERTONG    => [3 => 1,  4 => 3,   5 => 6],
    ERTIAO    => [3 => 1,  4 => 3,   5 => 6],
    SANTONG   => [3 => 2,  4 => 4,   5 => 10],
    WUTONG    => [3 => 3,  4 => 5,   5 => 12],
    WUTIAO    => [3 => 3,  4 => 5,   5 => 12],
    BAWAN     => [3 => 5,  4 => 10,  5 => 15],
    BAIBAN    => [3 => 6,  4 => 15,  5 => 30],
    HONGZHONG => [3 => 8,  4 => 20,  5 => 40],
    FACAI     => [3 => 10, 4 => 25,  5 => 50],
]);

// 图案出现概率 (普通地图 / 免费地图)
define('POSSIBLE',      [ERTONG => 50, ERTIAO => 50, SANTONG => 50, WUTONG => 30, WUTIAO => 30, BAWAN => 15, BAIBAN => 7,  HONGZHONG => 3, FACAI => 1, FREE => 200]);
define('FREEPOSSIBLE',  [ERTONG => 50, ERTIAO => 50, SANTONG => 50, WUTONG => 30, WUTIAO => 30, BAWAN => 10, BAIBAN => 3,  HONGZHONG => 2, FACAI => 1, FREE => 8]);

// 大奖评级 (3=大/2=中/1=小)
define('BIG_WIN', [3 => 40, 2 => 20, 1 => 10]);

// Wild 柱阈值 (万分之 N)
define('WILD_PERCENT', 5000);

// 跑马灯触发条件
define('HORSE', ['double' => 20, 'score' => 1]);

// 免费游戏档位
define('FREE_LEVEL_NORMAL', 0);   // 普通
define('FREE_LEVEL_BIG',    1);   // 大奖/超级
define('FREE_LEVEL_JACKPOT',2);   // 爆奖


/**
 * 麻将/老虎机游戏主逻辑
 */
class Table
{
    // ==================== 玩家状态 ====================
    private $userInfo = [];
    private $uid = 0;
    private $free = 0;             // 剩余免费次数
    private $map = [];             // 地图 (各轮)
    private $betGold = 0;          // 当前下注档位
    private $betDouble = 1;        // 当前下注倍率
    private $roomRule = [];        // 房间配置
    private $use = 0;              // 实际消耗金币
    private $mTimer = 0;
    private $mapPossible = [];     // 当前地图概率表 (5列)
    private $wildPossible = [];    // Wild 出现概率 (5列)

    // ==================== 单局结算 ====================
    private $cur_result = [];
    private $deal_map = [];
    private $all_score = 0;        // 整局总得分
    private $all_free = 0;         // 整局获得的免费次数
    private $free_get = 0;         // 免费轮累计得分
    private $save_maps = [];
    private $distime = 0;
    private $freedistime = 0;
    private $next_free_count = 999;

    // ==================== 免费保底 ====================
    private $normal_round_count = 0;
    private $free_guarantee_threshold = 0;
    private $is_free_guarantee = false;
    private $free_guarantee_min = 150;
    private $free_guarantee_max = 250;

    // ==================== 免费游戏档位 ====================
    private $free_total_limit_double = 30;
    private $free_total_min_double = 0;
    private $free_prize_level = 0;
    private $force_free_trigger = false;

    private $free_boom_left_count = 0;   // 爆奖在剩余第几转出现
    private $free_boom_min_double = 0;
    private $free_boom_max_double = 0;
    private $free_boom_used = false;

    private $guarantee_bet_gold = 0;
    private $guarantee_bet_double = 0;
    private $guarantee_count = 0;

    // ==================== 胜负统计 ====================
    private $all_win = 0;


    // ================================================================
    // 构造与入口
    // ================================================================

    public function __construct($msg)
    {
        $this->roomRule = $msg;
        $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
        $this->resetCurResult();
    }

    public function All_RECV($message)
    {
        switch ($message['event']) {
            case 'Msg_MJHLT_Start':
                $this->Msg_MJHLT_Start($message);
                break;
            case 'Msg_Game_Out':
                $this->Msg_Game_Out($message);
                break;
            case 'Msg_Game_RoomInfo':
                $this->Msg_Game_RoomInfo($message);
                break;
            default:
                Logic::SendError($message['uid'], $message['event'], '');
                MyTools::msg('uid:' . $message['uid'] . '-----UnKnown!!!!!!!--------' . $message['event'], true);
                break;
        }
    }

    // ================================================================
    // 房间信息 / 进房 / 离线
    // ================================================================

    private function Msg_Game_RoomInfo($message)
    {
        if ($this->uid && $this->uid == $message['uid']) {
            Logic::SendRight($this->uid, 'Msg_Game_RoomInfo', [
                'free'         => $this->free,
                'all_score'    => $this->all_score,
                'all_free'     => $this->all_free,
                'curgrade'     => $this->betGold,
                'curdouble'    => $this->betDouble,
                'map'          => $this->map,
                'max_multiple' => max($this->roomRule['score_arr']),
                'level'        => $this->roomRule['level'],
                'score_arr'    => $this->roomRule['score_arr'],
                'double_arr'   => $this->roomRule['double_arr'],
                'base_arr'     => [GAME_DOUBLE],
                'min_gold'     => $this->roomRule['min_gold'],
                'max_gold'     => $this->roomRule['max_gold'],
                'bet_min'      => $this->roomRule['bet_min'] ?? 10000,
                'bet_max'      => $this->roomRule['bet_max'] ?? 200000,
                'gold'         => $this->userInfo['gold'],
            ]);
        } else {
            Logic::SendError($message['uid'], 'Msg_Game_RoomInfo', '无效操作');
        }
    }

    public function UserOnline($client_id, $uid)
    {
        Timer::del($this->mTimer);
        $this->Msg_Game_RoomInfo(['uid' => $uid]);
    }

    public function UserOff($uid)
    {
        $this->saveGameCache();
        $this->mTimer = Timer::add(60, function () {
            $this->Msg_Game_Out(['uid' => $this->uid]);
        }, [], false);
    }

    public function EnterRoom($msg)
    {
        $this->uid = $msg['uid'];
        $ret = DBInstance::GetGameCache($this->uid, $this->roomRule['gtype'], $this->roomRule['level']);

        if (!$ret) {
            $this->betGold   = min($this->roomRule['score_arr']);
            $this->betDouble = min($this->roomRule['double_arr']);
            DBInstance::InsertGameCache([
                'uid'        => $this->uid,
                'gtype'      => $this->roomRule['gtype'],
                'level'      => $this->roomRule['level'],
                'map'        => '[]',
                'bet_gold'   => $this->betGold,
                'bet_double' => $this->betDouble,
                'free'       => 0,
            ]);
            $this->guarantee_count = 0;
        } else {
            $this->map  = $ret['map'];
            $this->free = $ret['free'];

            if ($this->free > 0) {
                $this->betGold   = $ret['bet_gold'];
                $this->betDouble = $ret['bet_double'];
            } else {
                $this->betGold   = min($this->roomRule['score_arr']);
                $this->betDouble = min($this->roomRule['double_arr']);
            }

            $this->guarantee_count = $ret['vals']['guarantee_count'] ?? 0;
            $this->all_score       = $ret['vals']['all_score']       ?? 0;
            $this->all_free        = $ret['vals']['all_free']        ?? 0;
            $this->use             = $this->betGold * $this->betDouble * GAME_DOUBLE;

            if ($this->free) {
                $this->distime     = $ret['vals']['distime'];
                $this->free_get    = $ret['vals']['free_get'];
                $this->save_maps   = $ret['vals']['save_maps'];
                $this->freedistime = $ret['vals']['freedistime'];
            }
        }

        $this->map      = [];
        $this->deal_map = [];
        $this->resetCurResult();

        if ($this->free <= 0) {
            $this->free = 0;
            $this->normal_round_count = 0;
            $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
            $this->free_prize_level = 0;
            $this->free_total_limit_double = 30;
            $this->free_total_min_double = 0;
            $this->free_boom_left_count = 0;
            $this->free_boom_min_double = 0;
            $this->free_boom_max_double = 0;
            $this->free_boom_used = false;
        }

        $this->userInfo = $msg;
        $this->Msg_Game_RoomInfo(['uid' => $this->uid]);
    }

    public function DisRoom($msg = [])
    {
        $this->Msg_Game_Out(['uid' => $this->uid]);
    }

    // ================================================================
    // 退出/转账 (与主逻辑无关的基础设施)
    // ================================================================

    private function Msg_Game_Out($message)
    {
        Timer::del($this->mTimer);

        $gold = DBInstance::GetTableOneWord('user_register', 'gold', ['uid' => $this->uid]);
        $bank = DBInstance::GetTableOneWord('user_register', 'bank', ['uid' => $this->uid]);
        Logic::SendRight($this->uid, 'Msg_Game_Out', ['gold' => $gold, 'bank' => $bank]);

        $this->saveGameCache();

        $olddata = [
            'rid'     => $this->roomRule['rid'],
            'win'     => [],
            'palyers' => [$this->uid => $this->userInfo],
            'result'  => ['uid' => []],
            'gtype'   => $this->roomRule['gtype'],
        ];
        Logic::RoomOld($olddata);
    }

    public function ChangeGold($msg)
    {
        $uid = $msg['uid'];
        $before = DBInstance::GetUser(['uid' => $uid]);
        DBInstance::IncrementGolds('bank', $uid, $msg['data']['num']);
        DBInstance::InsertUserProfit($uid, $msg['data']['from'], $msg['data']['type'], $msg['data']['num'], $before);
        $data = DBInstance::GetTableWords('user_register', 'bank,gold', ['uid' => $uid]);
        $this->userInfo['bank'] = $data['bank'];
        Logic::SendRight($this->uid, 'Msg_Hall_ChangeGolds', $data);
    }

    public function BackTransfer($message)
    {
        $ret = DBInstance::BackTransfer($message['data']['out_id']);
        $uid = $message['uid'];
        $data = $message['data'];
        $user = DBInstance::GetTableWords('user_register', 'bank,gold', ['uid' => $uid]);

        $message['data'] = [
            'bank'   => $user['bank'],
            'gold'   => $user['gold'],
            'status' => $ret ? 0 : 2,
        ];
        Common::SendToClient($message, $data['client_id']);

        if ($ret) {
            $data = ['bank' => $user['bank'], 'gold' => $user['gold']];
            $this->userInfo['bank'] = $data['bank'];
            Logic::SendRight($this->uid, 'Msg_Hall_ChangeGolds', $data);
        }
    }

    // ================================================================
    // 主流程: 一局游戏开始
    // ================================================================

    private function Msg_MJHLT_Start($message)
    {
        // -------- 1. 参数与校验 --------
        $betLevelIndex = $message['data']['score'] * $message['data']['double'];
        if ($betLevelIndex <= 0) {
            Logic::SendError($message['uid'], $message['event'], '等级错误');
            return;
        }
        if (empty(Logic::$betLevel[$betLevelIndex])) {
            $levelValues = array_values(Logic::$betLevel);
            Logic::$betLevel[$betLevelIndex] = !empty($levelValues) ? min($levelValues) : 1;
        }

        $use = ($this->free <= 0) ? ($message['data']['score'] * $message['data']['double'] * GAME_DOUBLE) : 0;

        if ($message['uid'] != $this->uid || $this->userInfo['gold'] < $use) {
            Logic::SendError($message['uid'], $message['event'], '无效操作');
            return;
        }

        $betMin = $this->roomRule['bet_min'] ?? 10000;
        $betMax = $this->roomRule['bet_max'] ?? 200000;
        if ($this->free <= 0 && ($use < $betMin || $use > $betMax)) {
            Logic::SendError($message['uid'], $message['event'], '投注金额超出范围');
            return;
        }

        // -------- 2. 免费档位与下注状态初始化 --------
        $this->prepareBetState($message['data']['score'], $message['data']['double'], $use);

        // -------- 3. 控制表读取 --------
        $logo_num = DBInstance::GetControlMap($this->uid, $this->roomRule['gtype'], $this->roomRule['level']);
        $level_index = $this->betGold * $this->betDouble;
        $control = $logo_num ? -2 : DBInstance::GetLBControl($this->uid, $this->roomRule['gtype'], Logic::$betLevel[$level_index]);
        $control_map = DBInstance::GetControlInfo('control_mjhlt', ['level' => $control]);

        $this->buildMapPossible($control, $control_map);

        // -------- 4. 免费下一转倒计时 --------
        if ($control >= 0) {
            $this->next_free_count--;
        }
        if (
            (isset($control_map[$control]['free_cirle']) && $this->next_free_count > $control_map[$control]['free_cirle'])
            || $use <= 0
            || $control < 0
        ) {
            $this->next_free_count = max($control_map[$control]['free_cirle'] ?? 0, 50);
        }

        // -------- 5. 免费轮参数 --------
        $is_free_round = ($this->free > 0 && $this->use > 0);
        $freeParams = $this->buildFreeRoundParams($is_free_round);

        // -------- 6. 生成地图 (最多 loop_max 次重摇) --------
        $loop_max = $this->calcLoopMax($is_free_round, $freeParams);
        $best = $this->rollMapLoop($loop_max, $is_free_round, $freeParams, $logo_num, $control);

        // 若爆奖模式未找到合格地图, 使用最佳结果兜底
        if ($is_free_round && $freeParams['need_boost'] && !$best['valid_found'] && $best['best_result'] !== null) {
            $this->map       = $best['best_map'];
            $this->deal_map  = $best['best_deal_map'];
            $this->cur_result= $best['best_result'];
            if ($freeParams['is_boom_round']) {
                $this->free_boom_used = true;
            }
        }

        // -------- 7. 兜底: 若最终结果仍超出限制, 清空本轮 --------
        $this->finalizeCurResult($is_free_round, $freeParams);

        // -------- 8. 结算新免费局 (进入新免费游戏时设置档位) --------
        if ($this->cur_result['getfree'] > 0 && $this->free <= 0) {
            $this->initFreePrizeLevel();
        }

        // -------- 9. 扣金币 / 发奖 / 写库 --------
        if ($this->free > 0) {
            $this->free--;
        }
        $this->free      += $this->cur_result['getfree'];
        $this->all_free  += $this->cur_result['getfree'];

        $user_win = array_sum($this->cur_result['score']);
        $this->all_win += $user_win - $use;
        $this->useGold($user_win - $use);

        Common::SyncPlatformPlayGame($this->uid, $use, $user_win, $this->roomRule['app_rid'] ?? '');

        $latest = DBInstance::GetTableWords('user_register', 'gold', ['uid' => $this->uid]);
        if ($latest && isset($latest['gold'])) {
            $this->userInfo['gold'] = $latest['gold'];
        }

        // 大奖评级
        $reward = 0;
        foreach (BIG_WIN as $key => $value) {
            if (intval($user_win / $this->use) >= $value) {
                $reward = $key;
                break;
            }
        }

        $this->all_score += $user_win;

        // -------- 10. 下发 --------
        $data = [
            'disappear'  => $this->cur_result['disappear'],
            'score'      => $this->cur_result['score'],
            'logo_info'  => $this->cur_result['logo_info'],
            'cur_gold'   => $this->cur_result['cur_gold'],
            'cur_time'   => $this->cur_result['cur_time'],
            'double_arr' => $this->cur_result['double_arr'],
            'free_logo'  => $this->cur_result['free_logo'],
            'curgrade'   => $this->betGold,
            'curdouble'  => $this->betDouble,
            'conscore'   => $use,
            'map'        => $this->map,
            'free'       => $this->free,
            'getfree'    => $this->cur_result['getfree'],
            'reward'     => $reward,
            'user_gold'  => $this->userInfo['gold'],
            'all_score'  => $this->all_score,
        ];

        $record_data = [
            'score'      => $this->cur_result['score'],
            'cur_gold'   => $this->cur_result['cur_gold'],
            'cur_time'   => $this->cur_result['cur_time'],
            'free_logo'  => $this->cur_result['free_logo'],
            'curgrade'   => $this->betGold,
            'curdouble'  => $this->betDouble,
            'conscore'   => $use,
            'free'       => $this->free,
            'getfree'    => $this->cur_result['getfree'],
            'reward'     => $reward,
            'all_score'  => $this->all_score,
        ];
        $this->save_maps[] = $record_data;

        // -------- 11. 免费保底计数 --------
        $this->updateGuaranteeState($use);

        Logic::SendRight($this->uid, 'Msg_MJHLT_Start', $data);

        // -------- 12. 后台统计 --------
        DBInstance::IncrementUserGet($this->uid, $user_win - $use);

        if (abs($control) != 2) {
            Logic::InsertProfit(Logic::$betLevel[$level_index], $user_win - $use);
        }

        if ($use) {
            $this->distime = count($this->map) - 1;
            $this->free_get = 0;
            $this->freedistime = 0;
        } else {
            $this->free_get += $user_win;
            $this->freedistime += count($this->map) - 1;
        }

        if ($this->free <= 0) {
            DBInstance::InsertGameRecord(
                $this->roomRule['gtype'],
                $this->roomRule['level'],
                $this->uid,
                $this->use,
                ($this->all_score - $this->use),
                $this->distime,
                $this->all_free,
                $this->save_maps,
                $this->freedistime
            );
        }

        $double = intval($user_win / $this->use);
        if ($user_win > HORSE['score'] && $double >= HORSE['double']) {
            Logic::HorseLamp($this->uid, $user_win, $double);
        }
    }

    // ================================================================
    // 子方法：Msg_MJHLT_Start 的拆解
    // ================================================================

    /**
     * 下注/免费状态准备
     */
    private function prepareBetState($new_bet_gold, $new_bet_double, $use)
    {
        if ($this->free > 0) {
            // 免费中: 不改动任何下注状态, 沿用进入免费时的档位
            return;
        }

        $this->all_score = 0;
        $this->all_free  = 0;
        $this->save_maps = [];

        // 注档变化时重置免费保底进度 (防止低注刷保底再跳高注)
        if (
            ($this->guarantee_bet_gold > 0 || $this->guarantee_bet_double > 0)
            && ($this->guarantee_bet_gold != $new_bet_gold || $this->guarantee_bet_double != $new_bet_double)
        ) {
            $this->normal_round_count = 0;
            $this->free_guarantee_threshold = mt_rand($this->free_guarantee_min, $this->free_guarantee_max);
            $this->is_free_guarantee = false;
        }

        $this->guarantee_bet_gold = $new_bet_gold;
        $this->guarantee_bet_double = $new_bet_double;
        $this->betGold   = $new_bet_gold;
        $this->betDouble = $new_bet_double;
        $this->use = $new_bet_gold * $new_bet_double * GAME_DOUBLE;
    }

    /**
     * 根据控制表构造 mapPossible / wildPossible
     */
    private function buildMapPossible($control, $control_map)
    {
        $this->mapPossible  = [];
        $this->wildPossible = [];

        if ($this->free > 0 && !empty($control_map[$control]['free_map']) && is_array($control_map[$control]['free_map'])) {
            $this->mapPossible = $control_map[$control]['free_map'];
            for ($i = 0; $i < 5; $i++) {
                $this->wildPossible[$i] = ($i && isset($control_map[$control]['free_wild'])) ? $control_map[$control]['free_wild'][$i] : 0;
            }
        } elseif (empty($control_map[$control]) || !is_array($control_map[$control]['map'])) {
            for ($i = 0; $i < 5; $i++) {
                $this->mapPossible[$i]  = POSSIBLE;
                $this->wildPossible[$i] = mt_rand(1, 6) ? 20 : 0;
            }
        } else {
            $this->mapPossible = $control_map[$control]['map'];
            for ($i = 0; $i < 5; $i++) {
                $this->wildPossible[$i] = ($i && isset($control_map[$control]['wild'])) ? $control_map[$control]['wild'][$i] : 0;
            }
        }
    }

    /**
     * 免费轮参数构造
     */
    private function buildFreeRoundParams($is_free_round)
    {
        $params = [
            'max_score'        => PHP_INT_MAX,
            'total_max_score'  => PHP_INT_MAX,
            'total_left_score' => PHP_INT_MAX,
            'reroll_min_score' => 0,
            'total_min_score'  => 0,
            'total_need_score' => 0,
            'need_boost'       => false,
            'boost_min_score'  => 0,
            'boost_max_score'  => PHP_INT_MAX,
            'is_boom_round'    => false,
        ];

        if (!$is_free_round) {
            return $params;
        }

        // 进入免费时的档位设置
        if ($this->free_prize_level == FREE_LEVEL_NORMAL) {
            $max_double       = 15;
            $reroll_min_double = 2;
        } elseif ($this->free_prize_level == FREE_LEVEL_BIG) {
            $max_double       = 130;
            $reroll_min_double = 20;
        } else {
            $max_double       = 300;
            $reroll_min_double = 80;
        }

        $params['max_score']       = $this->use * $max_double;
        $params['total_max_score'] = $this->use * $this->free_total_limit_double;
        $params['total_left_score']= max(0, $params['total_max_score'] - $this->free_get);
        $params['reroll_min_score']= $this->use * $reroll_min_double;
        $params['total_min_score'] = $this->use * $this->free_total_min_double;
        $params['total_need_score']= max(0, $params['total_min_score'] - $this->free_get);

        // 当前这转是不是指定的爆奖转?
        if (!$this->free_boom_used && $this->free_boom_left_count > 0 && $this->free == $this->free_boom_left_count) {
            $params['is_boom_round']   = true;
            $params['need_boost']      = true;
            $params['boost_min_score'] = $this->use * $this->free_boom_min_double;
            $params['boost_max_score'] = $this->use * $this->free_boom_max_double;
            // 单次爆奖不能超过本轮总剩余额度
            $params['boost_max_score'] = min($params['boost_max_score'], $params['total_left_score']);
            // 如果剩余额度低于爆奖最低值, 以剩余额度为准, 避免永远摇不到
            if ($params<?php

date_default_timezone_set('Asia/Shanghai');

use Workerman\Lib\Timer;

// ==================== 常量定义 ====================

define('ERTONG', 1);
define('ERTIAO', 2);
define('WUTONG', 3);
define('WUTIAO', 4);
