        $best_map   = [];
        $best_deal  = [];
        $best_result= null;
        $found      = false;

        for ($i = 0; $i < $loop_max; $i++) {
            $is_unset_logo = ($this->all_win < MAX_WIN_SCORE) ? false<?php

date_default_timezone_set('Asia/Shanghai');

