            // 免费: 超过单次上限, 丢弃并进入保底重摇
            if ($is_free_round && $total_score > $freeParams['max_score']) {
                continue;
            }

            // 免费: 超过累计剩余额度, 丢弃
            if ($is_free_round && $total_score > $freeParams['<?php

date_default_timezone_set('Asia/Shanghai');

use Workerman\Lib\Timer;

// ==================== 常量定义 ====================

define('ERTONG', 1);
define('ERTIAO', 2);
