define('DOUBLE', [
    ERTONG    => [3 => 1,  4 => 3,   5 => 6],
    ERTIAO    => [3 => 1,  4 => 3,   5 => 6],
    SANTONG   => [3 => 2,  4 => 4,   5 => 10],
    WUTONG    => [3 => 3,  4 => 5,   5 => 12],
    WUTIAO    => [3 => 3,  4 => 5,   5 => 12],
