// 控制逻辑中引用的外部常量
defined('MAX_WIN_SCORE') || define('MAX_WIN_SCORE', 1000000);

// 不同图案连击的赔付倍率表 (3连/4连/5连)
define('DOUBLE', [
    ERTONG    => [3 => 1,  4 => 3,   5 => 6],
    ERTIAO    => [3 => 1,  4 => 3,   5 => 6],
    SANTONG   => [3 => 2,  4 => 4,   5 => 10],
    WUTONG    => [3 => 3,  4 => 5,   5 => 12],
    WUTIAO    => [3 => 3,  4 => 5,   5 => 12],
    BAWAN     => [3 => 5,  4 => 10,  5 => 15],
