    {
        $num++;
        $is_free = ($this->free > 0);
        $del = mt_rand(0, 1);

        $map = [];
        $free_count = [];
        $logo_count = [];
        $unset_logo = [];

        if ($logo_num) {
            $forced_logo = max(array_keys($logo_num));
        }

