class Table
{
    // ==================== 玩家状态 ====================
    private $userInfo = [];
    private $uid = 0;
    private $free = 0;             // 剩余免费次数
    private $map = [];             // 地图 (各轮)
    private $betGold = 0;          // 当前下注档位
    private $betDouble = 1;        // 当前下注倍率
    private $roomRule = [];        // 房间配置
    private $use = 0;              // 实际消耗金币
    private $mTimer = 0;
    private $mapPossible = [];     // 当前地图概率表 (5列)
    private $wildPossible = [];    // Wild 出现概率 (5列)

    // ==================== 单局结算 ====================
    private $cur_result = [];
    private $deal_map = [];
    private $all_score = 0;        // 整局总得分
    private $all_free = 0;         // 整局获得的免费次数
    private $free_get = 0;         // 免费轮累计得分
    private $save_maps = [];
    private $distime = 0;
    private $freedistime = 0;
    private $next_free_count = 999;

    // ==================== 免费保底 ====================
    private $normal_round_count = 0;
    private $free_guarantee_threshold = 0;
    private $is_free_guarantee = false;
    private $free_guarantee_min = 150;
    private $free_guarantee_max = 250;

    // ==================== 免费游戏档位 ====================
    private $free_total_limit_double = 30;
    private $free_total_min_double = 0;
    private $free_prize_level = 0;
    private $force_free_trigger = false;

    private $free_boom_left_count = 0;   // 爆奖在剩余第几转出现
    private $free_boom_min_double = 0;
