                        $free_count[] = $i * 10 + $j;
                    }
                    $key = $map[$i][$j];
                    if (!isset($logo_count[$i][$key])) {
                        $logo_count[$i][$key] = 1;
                    } else {
                        $logo_count[$i][$key]++;
