                        if (!isset($logo_count[$i][$key]) && isset($unset_logo[$key]) && $del != $i && $i < 3) {
                            unset($possible[$key]);
                        }
                    }
                }

                // 控制模式: 屏蔽指定 logo
                if (isset($forced_logo)) {
                    unset($possible[$forced_logo]);
                }

                if (empty($possible)) {
                    $possible = $this->mapPossible[$i];
                }

                // 加权随机取一个
                $pick = $this->weightedPick($possible);
                $map[$i][$j] = $pick;

                if ($i == $del && $pick != BAIDA) {
                    $unset_logo[$pick] = 1;
                }
                if ($pick == FREE) {
                    $free_count[] = $i * 10 + $j;
                }

                // 免费金柱: 该列整行加成 +100
                if ($is_free && in_array($i, $golden_columns) && $pick != FREE && $pick != BAIDA) {
                    $map[$i][$j] += 100;
                } elseif (
                    $i && $i != 4 && $pick != FREE
                    && mt_rand(1, WILD_PERCENT) <= $this->wildPossible[$i]
                    && $num <= 3 && !$control
                ) {
                    $map[$i][$j] += 100;
                }
            }

            // 控制下的免费触发: 最后再塞一个 FREE
            if (
                !in_array(FREE, $map[$i])
                && empty($this->map)
                && $this->next_free_count <= 0
                && mt_rand(1, 100) <= 80
                && count($free_count) < 4
            ) {
                $_index = mt_rand(0, 4);
                $map[$i][$_index] = FREE;
                $free_count[] = $i * 10 + $_index;
            }
        }

        // 本转倍率 (免费 x2, 后续转再递乘)
