    private function placeGuaranteeFrees(&$map, &$free_count)
    {
        $positions = [];
        $middle_cols = [1, 2, 3];
        $middle_rows = [1, 2, 3];
        $max_free = 3;

        for ($loop = 0; $loop < 10 && count($positions) < $max_free; $loop++)<?php

