        $free_count = [];
        $logo_info = [];

        // 扫描格子: 0~4列 x 0~4行 (第5列第5行是边角, 略过)
        for ($i = 0; $i < 5; $i++) {
            $logo_count[$i] = [];
            for ($j = 0; $j < 5; $j++) {
                if ($j == 4 && ($<?php

