        // 扫描格子: 0~4列 x 0~4行 (第5列第5行是边角, 略过)
        for ($i = 0; $i < 5; $i++) {
            $logo_count[$i] = [];
            for ($j = 0; $j < 5; $j++) {
                if ($j == 4 && ($i == 0 || $i == 4)) {
                    continue;
                }

                $cell = $map[$i][$j];

                if ($cell == FREE) {
                    $free_count[] = $i * 10 + $j;
<?php

date_default_timezone_set('Asia/Shanghai');

use Workerman\Lib\Timer;

// ==================== 常量定义 ====================

define('ERTONG', 1);
