            for ($j = 0; $j < 5; $j++) {
                if ($j == 4 && ($i == 0 || $i == 4)) {
                    continue;
                }

                $cell = $map[$i][$j];

                if ($cell == FREE) {
                    $free_count[] = $i * 10 + $j;
                }

                // FREE / 首列的 BAIDA 不计入普通连击
                if<?php

date_default_timezone_set('Asia/Shanghai');

use Workerman\Lib\Timer;

