                }

                $cell = $map[$i][$j];

                if ($cell == FREE) {
                    $free_count[] = $i * 10 + $j;
                }

                // FREE / 首列的 BAIDA 不计入普通连击
                if ($cell == FREE || ($cell == BAIDA && !$i)) {
