            for ($j = 0; $j < 5; $j++) {
                if ($j == 4 && ($i == 0 || $i == 4)) {
                    continue;
                }

                $cell = $map[$i][$j];

                if ($cell == FREE) {
                    $free_count[] = $i * 10 + $j;
                }

                // FREE / 首列的 BAIDA 不计入普通连击
                if ($cell == FREE || ($cell == BAIDA && !$i)) {
                    continue;
                }

                $logo = ($cell >= 100) ? ($cell % 100) : $cell;
                if (!isset($logo_count[$i][$logo])) {
                    $logo_count[$i][$logo] = 1;
                } else {
                    $logo_count[$i][$logo]++;
                }
            }
        }

        // 以第一列为起点, 判定横向连击
        $start_col = $logo_count[0];
        $logo_get_max = [];

        foreach ($start_col as $logo => $start_num) {
            $found = $start_num;
            $hit_end = false;

            for ($i = 1; $i < 5; $i++) {
                $baida      = $logo_count[$i][BAIDA] ?? 0;
                $self_logo  = $logo_count<?php

date_default_timezone_set('Asia/Shanghai');

